with CurrencyConvertion as (
SELECT *, 
         CASE
         	WHEN sher = 0
         	THEN FIRST_VALUE(sher) OVER (PARTITION BY value_partition ORDER BY Tarikh) 
         	ELSE sher
         END AS new_sher
         ,CASE
         	WHEN SHER_EURO = 0
         	THEN FIRST_VALUE(SHER_EURO) OVER (PARTITION BY value_partitionEuro ORDER BY Tarikh) 
         	ELSE  SHER_EURO
         END AS new_sherEuro
 FROM (
          SELECT *
 ,SUM(CASE WHEN sher=0 THEN 0 ELSE 1 END) OVER (ORDER BY tarikh ) AS value_partition
 ,SUM(CASE WHEN SHER_EURO=0 THEN 0 ELSE 1 END) OVER (ORDER BY tarikh ) AS value_partitionEuro
          FROM SHERI_MTBE
 ) m
)

--------------------------------------------------------------- the below part should be a view is the database ----------------------------------------------------
,totals_raw AS (
    -- Step 1: per-row calculations
    SELECT
        CONCAT(
            CAST(CONVERT(BIGINT, POL.POL_OrderID) AS VARCHAR(20)),
            CAST(POL.POL_LineID AS VARCHAR(10))
        ) AS PurchaseOrderID,
        
        CONVERT(VARCHAR, HS.QOD_MOTSR) + '-' + CONVERT(VARCHAR, HS.QOD_MOTSR) AS ItemKey,

        -- PNL classification
        CASE
            WHEN HST.QOD_SHROT IN (5, 19, 30, 4)
              OR HST.QOD_SHROT IS NULL
                THEN 999
            ELSE HST.QOD_SHROT
        END AS PNLKey,

        -- Order quantity (only main item rows)
        CASE
            WHEN HS.QOD_SHROT = 0 THEN HS.CMOT
            ELSE 0
        END AS OrderQuantity,

        -- Line total in USD (exactly כמו הקטע ששלחת)
        CASE
            WHEN HS.MTBE = '$' THEN HS.MCHIR_ICH * HS.CMOT
            WHEN HS.MTBE = 'Eur' THEN HS.MCHIR_ICH * HS.CMOT * (SM.NEW_SHEREURO / NULLIF(SM.NEW_SHER, 0))
            ELSE HS.MCHIR_ICH * HS.CMOT * (
                    1 / CASE WHEN HC.SHER_MTBE = 0 THEN 1 ELSE HC.SHER_MTBE END
                 )
        END AS LineTotalNetUSD
    FROM HOTSAOT_COTROT HC
    LEFT JOIN HOTSAOT_SHOROT HS
        ON HC.NOMRTOR = HS.NOMRTOR
    LEFT JOIN PurchaseOrderLines POL
        ON CONCAT(
               CAST(CONVERT(BIGINT, POL.POL_OrderID) AS VARCHAR(20)),
               CAST(POL.POL_LineID AS VARCHAR(10))
           ) = CAST(HS.MS_MSMKH_QSHOR AS VARCHAR(30))
    LEFT JOIN HOTSAOT_SHROTIM_New HST
        ON HS.QOD_SHROT = HST.QOD_SHROT
    LEFT JOIN CurrencyConvertion SM
        ON SM.TARIKH = HC.T_ERKH
    WHERE 1 = 1
      AND CAST(SUBSTRING(HC.T_MSMKH, 1, 4) AS INT) >= 2018
      AND CAST(SUBSTRING(HC.T_MSMKH, 1, 4) AS INT) <= YEAR(GETDATE())
      AND HS.QOD_SHROT NOT IN (14)
),

totals AS (
    -- Step 2: aggregate like the DAX measure
    SELECT
        PurchaseOrderID,
        ItemKey,
        999 as PNLKey,
        SUM(LineTotalNetUSD) AS LineTotalNetUSD,       -- same as [Total Expenses USD]
        SUM(OrderQuantity)   AS OrderQuantity,     -- same as [Total Order Quantity (Hzmnot)]
        CAST(ROUND(SUM(LineTotalNetUSD) / NULLIF(SUM(OrderQuantity), 0), 2) AS FLOAT) AS UnitNetPriceUSD  -- Avg Price USD (Expenses)
    FROM totals_raw
    GROUP BY
        PurchaseOrderID,
        ItemKey
),

-- exchange_movements: merges former 'main' + 'base' — raw free shipments enriched with purchase cost
exchange_movements AS (
    SELECT
        TM.QOD_SHOLCH  AS DeliveredFrom,
        W.SHM_GORM     AS DeliveredFromName,
        ISNULL(b.MS_HZMNH, bb.MS_HZMNH) AS PurchaseOrderID,
        CASE
            WHEN ISNULL(b.MS_HZMNH, bb.MS_HZMNH) LIKE '2000%' THEN 'P' -- Purchase order
            ELSE 'E'                                                     -- Expense / other
        END AS Order_Type,
        CONVERT(VARCHAR, TM.QOD_MOTSR) + '-' + CONVERT(VARCHAR, TM.QOD_MOTSR) AS ItemKey,
        SUM(TM.MSHQL_NTO) AS qty_loaned,
        G.QOD_GORM     AS DeliveredTo,
        G.SHM_GORM     AS DeliveredToName,
        SUBSTRING(TARIKH_MSHLOCH, 1, 4) + '-' + SUBSTRING(TARIKH_MSHLOCH, 5, 2) AS [Date],
        -- price columns from totals (previously joined in the separate 'base' CTE)
        t.UnitNetPriceUSD,
        t.LineTotalNetUSD,
        t.OrderQuantity
    FROM TEODOT_MSHLOCH TM
    LEFT JOIN GORMIM G                   ON TM.QOD_MQBL        = G.QOD_GORM
    LEFT JOIN GORMIM W                   ON TM.QOD_SHOLCH       = W.QOD_GORM
    LEFT JOIN QISHOR_RCSH_LMCIRH a       ON a.MS_TEODT_MCIRH   = TM.MS_TEODH
    LEFT JOIN QISHOR_T_MSHLOCH_HZMNOT b  ON a.MS_TEODT_RCSH    = b.MS_T_MSHLOCH
    LEFT JOIN QISHOR_T_MSHLOCH_HZMNOT bb ON bb.MS_T_MSHLOCH    = TM.MS_TEODH
    LEFT JOIN (
        SELECT PurchaseOrderID, ItemKey, UnitNetPriceUSD, LineTotalNetUSD, OrderQuantity
        FROM totals
        WHERE PNLKey = 999
          AND OrderQuantity <> 0
    ) t ON ISNULL(b.MS_HZMNH, bb.MS_HZMNH) = t.PurchaseOrderID
    WHERE TM.MCHIR_ICH = 0                         -- Only free/loaned shipments
      AND G.AOPI_PEILOT NOT IN (N'פחת', N'אחסון') -- Exclude waste/storage
      AND SUBSTRING(TARIKH_MSHLOCH, 1, 4) + '-' + SUBSTRING(TARIKH_MSHLOCH, 5, 2) >= '2024-01'
    GROUP BY
        SUBSTRING(TARIKH_MSHLOCH, 1, 4) + '-' + SUBSTRING(TARIKH_MSHLOCH, 5, 2),
        TM.QOD_SHOLCH, W.SHM_GORM,
        b.MS_HZMNH, bb.MS_HZMNH,
        CONVERT(VARCHAR, TM.QOD_MOTSR) + '-' + CONVERT(VARCHAR, TM.QOD_MOTSR),
        G.QOD_GORM, G.SHM_GORM,
        t.UnitNetPriceUSD, t.LineTotalNetUSD, t.OrderQuantity
),

exchange_p_orders AS (
    -- P-type movements only: the original purchases that exchanges are matched against
    SELECT
        DeliveredFrom,
        DeliveredFromName,
        PurchaseOrderID,
        ItemKey,
        SUM(qty_loaned)        AS quantity,
        DeliveredTo,
        DeliveredToName,
        [Date]                 AS Purchase_Date,
        MAX(UnitNetPriceUSD)   AS max_unit_price,
        MAX(LineTotalNetUSD)   AS max_LineTotalNetUSD,
        MAX(OrderQuantity)     AS max_OrderQuantity
    FROM exchange_movements
    WHERE Order_Type = 'P'
    GROUP BY
        DeliveredFrom, DeliveredFromName,
        PurchaseOrderID, ItemKey,
        DeliveredTo, DeliveredToName,
        [Date]
),

-- exchange_priced: merges former 'final' + 'final2' — ranks and keeps only the best purchase match
exchange_priced AS (
    SELECT
            b.DeliveredFrom,
            b.DeliveredFromName,
            b.PurchaseOrderID  AS Exchange_order,
            b.[Date]           AS Exchange_Order_Date,
            b.ItemKey,
            b.qty_loaned       AS Qty_Sold,
            p.PurchaseOrderID  AS Purchase,
            p.Purchase_Date,
            p.max_unit_price   AS UnitNetPriceUSD,
            p.max_LineTotalNetUSD AS LineTotalNetUSD,
            p.max_OrderQuantity   AS OrderQuantity,
            ship_sub.ShipID,   -- ship from the related purchase order
            ROW_NUMBER() OVER (
                PARTITION BY b.ItemKey,b.PurchaseOrderID
                ORDER BY p.Purchase_Date DESC
            ) AS rn
        FROM exchange_movements b
        LEFT JOIN exchange_p_orders p
            ON  b.DeliveredFrom = p.DeliveredTo
            AND b.ItemKey       = p.ItemKey
        -- Look up the ship that delivered the related purchase order.
        -- p.PurchaseOrderID = CONCAT(POL_OrderID, POL_LineID) — same format as totals_raw.
        -- Must include POL_LineID in the key, otherwise it never matches.
        LEFT JOIN (
            SELECT
                CONCAT(
                    CAST(CONVERT(BIGINT, POL.POL_OrderID) AS VARCHAR(20)),
                    CAST(POL.POL_LineID AS VARCHAR(10))
                )              AS PurchaseOrderID,
                MAX(sl.ShipID) AS ShipID
            FROM PurchaseOrderLines POL
            JOIN ShipsArrivals sa ON POL.POL_ShipArrivalID = sa.SA_ID
            JOIN ShipList      sl ON sa.SA_ShipID          = sl.ShipID
            GROUP BY POL.POL_OrderID, POL.POL_LineID
        ) ship_sub ON ship_sub.PurchaseOrderID = CAST(p.PurchaseOrderID AS VARCHAR(20))
        WHERE DATEDIFF(MONTH,
				CAST(b.[Date] + '-01' AS DATE),
				CAST(p.Purchase_Date + '-01' AS DATE)
				)    BETWEEN -3 AND 0
)

-----------------------------------------------------------------------------------------------------------------------------------------------
,purchase_orders as (

----Invoice--
SELECT
	 CAST(CCS.HZMNT_RCSH AS VARCHAR)			AS PurchaseOrderID,
     'Invoice'									AS DocName,
     NULL										AS SupplierKey,
     CAST(SUBSTRING(CCS.T_CHSHBONIT,1,4) + '-' + SUBSTRING(CCS.T_CHSHBONIT,5,2) + '-' + SUBSTRING(CCS.T_CHSHBONIT,7,2) AS DATE) AS [Value Date],
     CAST(CONVERT(VARCHAR, POL_ProductID) AS VARCHAR) + '-' + CAST(CONVERT(VARCHAR, M.ServiceCode) AS VARCHAR) + 'S' AS ItemKey,
     CAST(ROUND(CCS.MCHIR_ICH_LLA_ME_M / NULLIF(CASE WHEN SHER_LCHISHOB <> 0 THEN SHER_LCHISHOB ELSE CC2.new_sher END, 0), 2) AS FLOAT) * -1  AS UnitNetPriceUSD,
     CCS.MSHQL_NTO                   AS Quantity,
     CASE WHEN CCS.QOD_MOTSR = 0 THEN CCS.MSHQL_NTO ELSE 0 END AS OrderQuantity,
     HST.QOD_SHROT                           AS PNLKey,
	 HST.PNL as [PNL Code],
     CAST(ROUND(CCS.CMOT * (CCS.MCHIR_ICH_LLA_ME_M / NULLIF(CASE WHEN SHER_LCHISHOB <> 0 THEN SHER_LCHISHOB ELSE CC2.new_sher END, 0)), 2) AS FLOAT) * -1 AS LineTotalNetUSD,
     CONVERT(INT, CONVERT(VARCHAR, SUBSTRING(CCS.T_CHSHBONIT,1,4) + SUBSTRING(CCS.T_CHSHBONIT,5,2))) AS YearMonth,
	 null as ShipID,
    'Invoice'                                AS DocType,
	CASE WHEN SHER_LCHISHOB <> 0 THEN SHER_LCHISHOB ELSE CC2.new_sher END as [NEW_SHER]
FROM [dbo].[CHIOBI_CHOTS_COTROT] CC
LEFT JOIN [dbo].[CHIOBI_CHOTS_SHOROT] CCS
       ON CC.MS_CHSHBONIT = CCS.MS_CHSHBONIT
LEFT JOIN CurrencyConvertion CC2
       ON CCS.[TARIKH_MSHLOCH] = CC2.Tarikh
LEFT JOIN (select DISTINCT
			POL_SQL_POID, POL_ProductID
			from PurchaseOrderLines POL	) POL
		ON CCS.HZMNT_RCSH = POL.POL_SQL_POID
LEFT JOIN MOTSRIM M
	ON CCS.QOD_MOTSR = M.QOD_MOTSR
LEFT JOIN HOTSAOT_SHROTIM_New HST 
	ON M.ServiceCode = HST.QOD_SHROT
	where CAST(SUBSTRING(CCS.T_CHSHBONIT,1,4) + '-' + SUBSTRING(CCS.T_CHSHBONIT,5,2) + '-' + SUBSTRING(CCS.T_CHSHBONIT,7,2) AS DATE) >= '2024-01-01'

UNION ALL
	------Import--------
SELECT

		CONCAT(
			CAST(CONVERT(BIGINT, POL.POL_OrderID) AS VARCHAR(20)),
			CAST(POL.POL_LineID AS VARCHAR(10))
		 )	as 'PurchaseOrderID'
		,'Import' AS 'DocName'  -- was: 'Order Expenses'
		,CAST(
		  MAX(
			CASE WHEN HS.QOD_SHROT = 0
				 THEN CONVERT(INT, CONVERT(VARCHAR, HC.QOD_SPQ))
			END
		  ) OVER (PARTITION BY HS.MS_MSMKH_QSHOR)
			AS VARCHAR)	 AS 'SupplierKey'
		,CASE 
			WHEN HS.MS_MSMKH_QSHOR = 0 
			  THEN CONVERT(date, HC.T_ERKH, 112)
			ELSE
			  MAX(
				CASE WHEN HS.QOD_SHROT = 0 
					 THEN CONVERT(date, HC.T_ERKH, 112) 
				END
			  ) OVER (
				PARTITION BY 
				  CASE 
					WHEN HS.MS_MSMKH_QSHOR = 0 
					  THEN HZ.MSPR_HZMNH 
					ELSE HS.MS_MSMKH_QSHOR 
				  END
			  )
		  END AS 'Value Date'
		,CASE
			WHEN  HST.QOD_SHROT IS NULL OR HS.QOD_SHROT IN (5, 19, 30, 4) THEN cast(CONVERT(INT, CONVERT(VARCHAR,HS.QOD_MOTSR)) as varchar)+ '-' + cast(CONVERT(INT, CONVERT(VARCHAR,HS.QOD_MOTSR)) as varchar) -- העמסת עליות הובלה והפרש מחיר על המוצר
			ELSE cast(CONVERT(INT, CONVERT(VARCHAR,HS.QOD_MOTSR)) as varchar)+ '-' + cast(CONVERT(INT, CONVERT(VARCHAR,HST.QOD_SHROT)) as varchar)+'S' 
			END		AS 'ItemKey'

		 ,CASE
			WHEN HST.QOD_SHROT IS NOT NULL THEN
				CASE
					WHEN HS.MTBE = '$' THEN
						CAST(ROUND(HS.MCHIR_ICH / NULLIF(POL.POL_FinalWeightReceived, 0), 2) AS FLOAT)
					WHEN HS.MTBE = 'Eur' THEN
						CAST(ROUND(
							HS.MCHIR_ICH * (SM.NEW_SHEREURO / NULLIF(SM.NEW_SHER, 0)) / NULLIF(POL.POL_FinalWeightReceived, 0)
						, 2) AS FLOAT)
					ELSE
						CAST(ROUND(
							HS.MCHIR_ICH * (1 / NULLIF(HC.SHER_MTBE, 0)) / NULLIF(POL.POL_FinalWeightReceived, 0)
						, 2) AS FLOAT)
				END
			ELSE
				CASE
					WHEN HS.MTBE = '$' THEN CAST(ROUND(HS.MCHIR_ICH, 2) AS FLOAT)
					WHEN HS.MTBE = 'Eur' THEN
						CAST(ROUND(
							HS.MCHIR_ICH * (SM.NEW_SHEREURO / NULLIF(SM.NEW_SHER, 0))
						, 2) AS FLOAT)
					ELSE
						CAST(ROUND(
							HS.MCHIR_ICH * (1 / NULLIF(HC.SHER_MTBE, 0))
						, 2) AS FLOAT)
				END
		END AS 'UnitNetPriceUSD'
		,HS.CMOT AS 'Quantity'
		,CASE WHEN HS.QOD_SHROT = 0 then HS.CMOT
				ELSE 0
				END									AS 'OrderQuantity'
		,CASE 
			WHEN HST.QOD_SHROT IN (5, 19, 30, 4,18) OR HST.QOD_SHROT IS NULL 
			THEN 999
			ELSE HST.QOD_SHROT
		END											AS 'PNLKey' ----------  העמסת עליות הובלה על המוצר והפרש מחיר
			,case when HST.QOD_SHROT IN (5, 19, 30, 4,18) OR HST.QOD_SHROT IS NULL  then 1010 
			else HST.PNL end as [PNL Code]
			,CAST(ROUND(CASE
	         WHEN HS.MTBE = '$' THEN HS.MCHIR_ICH * HS.CMOT
			 WHEN HS.MTBE = 'Eur' THEN HS.MCHIR_ICH * HS.CMOT * (SM.NEW_SHEREURO / NULLIF(SM.NEW_SHER, 0))
	         ELSE HS.MCHIR_ICH * HS.CMOT * (1 / CASE WHEN HC.SHER_MTBE = 0 THEN 1 ELSE HC.SHER_MTBE END)
         END, 2) AS FLOAT) AS 'LineTotalNetUSD'
		,CONVERT(INT, CONVERT(VARCHAR,SUBSTRING(HS.T_ERKH,1,4) + SUBSTRING(HS.T_ERKH,5,2))) AS YearMonth
		,sl.ShipID
		,CASE 
		    WHEN HS.QOD_SHROT IN (5, 19, 30, 20, 4) THEN N'סחורה'
		    ELSE HC.SOG_MSMKH
		END												as DocType
		,SM.NEW_SHER
FROM HOTSAOT_COTROT HC
LEFT JOIN HOTSAOT_SHOROT HS ON HC.NOMRTOR = HS.NOMRTOR
LEFT JOIN PurchaseOrderLines POL ON CONCAT(
										CAST(CONVERT(BIGINT, POL.POL_OrderID) AS VARCHAR(20)),
										CAST(POL.POL_LineID AS VARCHAR(10))
									)	
										= CAST(HS.MS_MSMKH_QSHOR AS VARCHAR(30))
LEFT JOIN HZMNOT HZ ON (HS.MS_MSMKH_QSHOR = HZ.MSPR_HZMNH)
LEFT JOIN HOTSAOT_SHROTIM_New HST ON HS.QOD_SHROT = HST.QOD_SHROT
LEFT JOIN ShipsArrivals sa ON POL.POL_ShipArrivalID = sa.SA_ID
LEFT JOIN ShipList sl ON sa.SA_ShipID = sl.ShipID
LEFT JOIN PurchaseOrder PO ON POL.POL_OrderID = PO.PO_OrderID
LEFT JOIN CurrencyConvertion SM  ON SM.TARIKH=HC.T_ERKH

WHERE 1=1
and Cast(SUBSTRING(HC.T_MSMKH,1,4) as int) >=2018 and Cast(SUBSTRING(HC.T_MSMKH,1,4) as int) <= YEAR(GETDATE())
and HS.QOD_SHROT NOT IN (14)
and CONCAT(CAST(CONVERT(BIGINT, POL.POL_OrderID) AS VARCHAR(20)),CAST(POL.POL_LineID AS VARCHAR(10))) <> ' '
and  cast( HC.T_ERKH as date) >= '2024-01-01'

UNION ALL

-----Exchange----
SELECT
    CAST(HZ.MSPR_HZMNH AS VARCHAR)                                      AS PurchaseOrderID,
    'Swap'                                                          AS DocName,  -- was: 'Orders'
    t.DeliveredFrom	                                            AS SupplierKey,
    CAST(SUBSTRING(HZ.T_ASPQH,1,4) + '-' + SUBSTRING(HZ.T_ASPQH,5,2) + '-' + SUBSTRING(HZ.T_ASPQH,7,2)
         AS DATE)                                                       AS [Value Date],
    CAST(CONVERT(INT, CONVERT(VARCHAR,HZ.MOTSR_MOZMN)) AS VARCHAR) + '-' +
    CAST(CONVERT(INT, CONVERT(VARCHAR,HZ.MOTSR_MOZMN)) AS VARCHAR)      AS ItemKey,
    t.UnitNetPriceUSD                                                   AS UnitNetPriceUSD,
    HZ.CMOT_MOZMNT                                                      AS Quantity,
    t.OrderQuantity                                                     AS OrderQuantity,
    999                                                                 AS PNLKey,
	1010  as [PNL Code],
    t.LineTotalNetUSD                                                  AS LineTotalNetUSD,
    CONVERT(INT, CONVERT(VARCHAR, SUBSTRING(HZ.T_ASPQH,1,4) + SUBSTRING(HZ.T_ASPQH,5,2))) AS YearMonth,
    t.ShipID                                                            AS ShipID,  -- ship from the related purchase order
    'Order'                                                             AS DocType,
    SM.NEW_SHER
FROM HZMNOT HZ
LEFT JOIN CurrencyConvertion SM
    ON SM.TARIKH = HZ.T_HZMNH
LEFT JOIN exchange_priced t
    ON t.Exchange_order = HZ.MSPR_HZMNH
   AND t.ItemKey =
        CAST(CONVERT(INT, CONVERT(VARCHAR,HZ.MOTSR_MOZMN)) AS VARCHAR) + '-' +
        CAST(CONVERT(INT, CONVERT(VARCHAR,HZ.MOTSR_MOZMN)) AS VARCHAR)
   AND t.rn = 1
WHERE CAST(SUBSTRING(HZ.T_HZMNH,1,4) AS INT) BETWEEN 2018 AND YEAR(GETDATE())
  AND HZ.OrderStatus <> 3
  AND HZ.ActionType IN (6,7)
  AND YEAR(CAST(SUBSTRING(HZ.T_ASPQH,1,4) + '-' + SUBSTRING(HZ.T_ASPQH,5,2) + '-' + SUBSTRING(HZ.T_ASPQH,7,2) AS DATE))  >= 2024
  )

,inv AS (
    -- One row per (ItemKey, calendar-month): last day's price in that month.
    -- Price is set by item+date, not by warehouse — any warehouse shares the same item price.
    SELECT ItemKey, [Date], WH_Price
    FROM (
        SELECT
            CONVERT(VARCHAR, src.ItemKey) + '-' + CONVERT(VARCHAR, src.ItemKey) AS ItemKey,
            src.[Date],
            CAST(ROUND(src.LastFOTPrice,     2) AS FLOAT) AS LastFOTPrice,
            CAST(ROUND(src.WeightedExpenses, 2) AS FLOAT) AS WeightedExpenses,
            CAST(ROUND(COALESCE(NULLIF(src.WeightedExpenses, 0), src.LastFOTPrice), 2) AS FLOAT) AS WH_Price,
            ROW_NUMBER() OVER (
                PARTITION BY src.ItemKey, YEAR(src.[Date]), MONTH(src.[Date])
                ORDER BY src.[Date] DESC
            ) AS month_rn
        FROM (
            -- Regular warehouses
            SELECT
                inv.ProductID      AS ItemKey,
                inv.DueDate        AS [Date],
                pcost.FotFlat      AS LastFOTPrice,
                pcost.WeightedExpenses,
                inv.Version,
                ROW_NUMBER() OVER (PARTITION BY inv.DueDate, inv.SupplierID, inv.ProductID
                                   ORDER BY inv.Version DESC) AS MaxVersion
            FROM tblInventory inv
            LEFT JOIN tblProductsCost pcost
                ON  inv.DueDate   = pcost.DueDate
                AND inv.ProductID = pcost.ProductCode
                AND inv.Version   = pcost.Version
            WHERE inv.SupplierID IN (1411, 1367, 1366, 1289, 1101, 943)
              AND inv.DueDate >= '2024-01-01'

            UNION ALL

            -- Warehouse 1144: items from BT movements, prices from tblProductsCost
            SELECT
                tm.ItemKey,
                pc.DueDate         AS [Date],
                pc.FotFlat         AS LastFOTPrice,
                pc.WeightedExpenses,
                mv.MAXVERSION      AS Version,
                ROW_NUMBER() OVER (PARTITION BY pc.DueDate, tm.ItemKey
                                   ORDER BY mv.MAXVERSION DESC) AS MaxVersion
            FROM (
                SELECT DISTINCT QOD_PRIT AS ItemKey,
                       CAST(SUBSTRING(T_TNOEH,1,4)+'-'+SUBSTRING(T_TNOEH,5,2)+'-'+SUBSTRING(T_TNOEH,7,2) AS DATE) AS [Date]
                FROM BT.dbo.TNOEOT_MLAI_CLLI
                WHERE QOD_GORM <> 1
                  AND CAST(SUBSTRING(T_TNOEH,1,4) AS INT) BETWEEN 2024 AND YEAR(GETDATE())
                  AND (SOG_TNOEH_CN_ITS_SP_HE LIKE N'%כ%' OR SOG_TNOEH_CN_ITS_SP_HE LIKE N'%י%')
            ) tm
            LEFT JOIN (SELECT DueDate, ProductCode, MAX(Version) AS MAXVERSION
                       FROM tblProductsCost
                       GROUP BY DueDate, ProductCode) mv
                ON  mv.DueDate     = tm.[Date]
                AND mv.ProductCode = tm.ItemKey
            LEFT JOIN tblProductsCost pc
                ON  pc.Version     = mv.MAXVERSION
                AND pc.DueDate     = mv.DueDate
                AND pc.ProductCode = mv.ProductCode
            GROUP BY tm.ItemKey, pc.DueDate, pc.FotFlat, pc.WeightedExpenses, mv.MAXVERSION
        ) src
        WHERE src.MaxVersion = 1
    ) daily
    WHERE daily.month_rn = 1
)

-- Resolves the primary DocName per PurchaseOrderID before aggregation.
-- A PO can have rows of multiple types (e.g. Import + Invoice).
-- Priority: Import > Exchange > Invoice.
,po_doctype AS (
    SELECT DISTINCT
        PurchaseOrderID,
        CASE
            WHEN EXISTS (
                SELECT 1 FROM purchase_orders pe2
                WHERE pe2.PurchaseOrderID = pe.PurchaseOrderID
                  AND pe2.DocName = 'Import'
            ) THEN 'Import'
            WHEN EXISTS (
                SELECT 1 FROM purchase_orders pe2
                WHERE pe2.PurchaseOrderID = pe.PurchaseOrderID
                  AND pe2.DocName = 'Swap'
            ) THEN 'Swap'
            ELSE 'Invoice'
        END AS DocName
    FROM purchase_orders pe
)

,P_costs as (
    select
	pe.PurchaseOrderID,
	dt.DocName,
	min([Value Date]) as ValueDate,
	max(case when [PNLKey] = 999 then SupplierKey else null end) as SupplierKey,
	max(ShipID) as boat,
	SUM(CASE WHEN [PNL Code] = 2270 THEN LineTotalNetUSD ELSE 0 END) as DischargeCosts,
	CAST(ROUND(SUM(CASE WHEN [PNL Code] = 1201 THEN LineTotalNetUSD ELSE 0 END) / NULLIF(SUM(orderquantity), 0), 2) AS FLOAT) as [demurrage / Despatch],
	CAST(ROUND(SUM(CASE WHEN [PNL Code] = 1111 THEN LineTotalNetUSD ELSE 0 END) / NULLIF(SUM(orderquantity), 0), 2) AS FLOAT) as [Shortage],
	CAST(ROUND(SUM(CASE WHEN [PNL Code] not in (1010,2270,1201,1111) THEN LineTotalNetUSD ELSE 0 END) / NULLIF(SUM(orderquantity), 0), 2) AS FLOAT) as [Other_Expenses],
	sum (orderquantity) as orderquantity,
	sum(LineTotalNetUSD) as LineTotalNetUSD,
	CAST(ROUND(
		SUM(CASE WHEN PNLKey = 999 THEN LineTotalNetUSD ELSE 0 END)
		/ NULLIF(SUM(CASE WHEN PNLKey = 999 THEN OrderQuantity ELSE 0 END), 0)
	, 2) AS FLOAT) AS Cif_price,
	MAX(pe.NEW_SHER) AS NEW_SHER
  from purchase_orders pe
  LEFT JOIN po_doctype dt ON dt.PurchaseOrderID = pe.PurchaseOrderID
  group by pe.PurchaseOrderID, dt.DocName
  )
,sales as (
  SELECT 
	'Invoice' AS 'DocName'
		,Case
			WHEN CS.QOD_MOTSR = TM.QOD_MOTSR
				THEN 'Item'
			ELSE 'Additional Expense'
		END AS 'LineType'
		,CONVERT(VARCHAR,CS.QOD_LQOCH) 'AccountKey' -- customer from invoices in case you need just invoices 
		,SUBSTRING(CS.T_CHSHBONIT,1,4) + '-' + SUBSTRING(CS.T_CHSHBONIT,5,2) + '-' + SUBSTRING(CS.T_CHSHBONIT,7,2) AS 'Date' -- Invoice date  
		,CAST(CONVERT(INT, CONVERT(VARCHAR,AM.QOD))as varchar) 'AgentKey' -- Agent from Customer method
		,CAST( CONVERT(VARCHAR,CS.QOD_MOTSR) as varchar) +'-' + CAST( CONVERT(VARCHAR,CS.QOD_MOTSR) as varchar) AS 'ItemKey'
		,CAST(ROUND(CS.MCHIR_ICH_LLA_ME_M / NULLIF(CASE WHEN SHER_LCHISHOB <> 0 THEN SHER_LCHISHOB ELSE 1 END, 0), 2) AS FLOAT) AS 'UnitNetPriceUSD'
		,cast(ROUND(CS.MSHQL_NTO,2)AS FLOAT)  AS 'Quantity'
		,case
		when TM.ActionType = 11 and CS.QOD_MOTSR = TM.QOD_MOTSR then TM.MSHQL_NTO
		else 0 end
	as qty_cif
	,case
		when TM.ActionType = 1 and CS.QOD_MOTSR = TM.QOD_MOTSR then TM.MSHQL_NTO
		else 0 end
	as qty_fot
	,case
		when TM.ActionType = 1 then 'FOT'
		WHEN TM.ActionType = 11 then 'CIF'
		WHEN TM.ActionType = 12 then 'FOT Premium'
	else null 
	end as SalesType
		,CASE
			WHEN CS.QOD_MOTSR=TM.QOD_MOTSR
				THEN 0
			ELSE Cs.CMOT
		END as AdditionalQuantity
		,CAST(ROUND(
			CASE
				WHEN CS.QOD_MOTSR <> 0
					THEN (CS.MCHIR_ICH_LLA_ME_M * CS.MSHQL_NTO) / NULLIF(CASE WHEN SHER_LCHISHOB <> 0 THEN SHER_LCHISHOB ELSE CC.new_sher END, 0)
				ELSE CS.MCHIR_ICH_LLA_ME_M / NULLIF(CASE WHEN SHER_LCHISHOB <> 0 THEN SHER_LCHISHOB ELSE CC.new_sher END, 0)
			END
			+
			CASE
				WHEN CS.QOD_MOTSR = TM.QOD_MOTSR THEN 0
				WHEN TM.QOD_MOTSR IS NULL         THEN 0
				ELSE Cs.CMOT * (CS.MCHIR_ICH_LLA_ME_M / NULLIF(CASE WHEN SHER_LCHISHOB <> 0 THEN SHER_LCHISHOB ELSE CC.new_sher END, 0))
			END
		, 2) AS FLOAT) AS 'LineTotalNet_USD' --Invoices are always in NIS
		,CONVERT(INT, CONVERT(VARCHAR,SUBSTRING(CS.T_CHSHBONIT,1,4) + SUBSTRING(CS.T_CHSHBONIT,5,2))) AS YearMonth
		, TM.MS_TEODH as 'DeliveryNote'
		,CASE
			WHEN SUBSTRING(TM.TARIKH_MSHLOCH,1,4) = '0000'
				THEN CAST(SUBSTRING(CS.T_CHSHBONIT,1,4) + '-' + SUBSTRING(CS.T_CHSHBONIT,5,2) + '-' + SUBSTRING(CS.T_CHSHBONIT,7,2) as date)
			ELSE CAST(ISNULL(SUBSTRING(TM.TARIKH_MSHLOCH,1,4) + '-' + SUBSTRING(TM.TARIKH_MSHLOCH,5,2) + '-' + SUBSTRING(TM.TARIKH_MSHLOCH,7,2),
		ISNULL(SUBSTRING(FTM.FirstDeliveryDateTM,1,4) + '-' + SUBSTRING(FTM.FirstDeliveryDateTM,5,2) + '-' + SUBSTRING(FTM.FirstDeliveryDateTM,7,2),
		SUBSTRING(CS.T_CHSHBONIT,1,4) + '-' + SUBSTRING(CS.T_CHSHBONIT,5,2) + '-' + SUBSTRING(CS.T_CHSHBONIT,7,2)))
		AS date) 
		END as 'DeliveryDate'
		,HZ.MSPR_HZMNH as 'OrderID'
		,TM.QOD_SHOLCH as 'SupplierWarehouse'
		,TM.ActionType							as 'ActionType'
		,CASE 
			WHEN TM.ActionType = 6 THEN G.AOPI_PEILOT
			ELSE act.ActionType
		END										as 'ActionTypeDesc'										
		,'0'									as 'AdjustmentFlag'
		,'Sales'								as  'QuantityCategory'
		,NULL									as  'TransactionType'  -- invoices are always direct sales
FROM CHSHBONIOT_COTROT CH
Left Join GORMIM G
	on CH.QOD_LQOCH = G.QOD_GORM
Left Join TBLT_ANSHI_MCIROT AM 
	on AM.SHM_AISH_MCIROT = G.AISH_MCIROT_MTPL
LEFT JOIN CHSHBONIOT_SHOROT CS 
    ON CH.MS_CHSHBONIT = CS.MS_CHSHBONIT
LEFT JOIN TEODOT_MSHLOCH TM 
	ON CS.MS_T_MSHLOCH = TM.MS_TEODH
LEFT JOIN (SELECT MS_CHSHBONIT , Min (TM.TARIKH_MSHLOCH) as 'FirstDeliveryDateTM',Min (CHS.TARIKH_MSHLOCH) as 'FirstDeliveryDateCHS'
			FROM CHSHBONIOT_SHOROT CHS
			Left Join TEODOT_MSHLOCH TM
				ON TM.MS_TEODH = CHS.MS_T_MSHLOCH
			Where 1=1
			AND TM.TARIKH_MSHLOCH <>00000000
			AND CHS.TARIKH_MSHLOCH <>00000000
			Group By CHS.MS_CHSHBONIT) FTM
	ON FTM.MS_CHSHBONIT = CH.MS_CHSHBONIT
Left Join (SELECT MS_HZMNH,MS_T_MSHLOCH
			FROM QISHOR_T_MSHLOCH_HZMNOT
			) HZT
	on TM.MS_TEODH = HZT.MS_T_MSHLOCH
Left Join HZMNOT HZ
	on HZ.MSPR_HZMNH = HZT.MS_HZMNH
left join TBLT_PEOLOT_HZMNH_T_MSHLOCH act
	on TM.ActionType = act.MS_AOPTSIH
left join CurrencyConvertion CC 
	ON cs.[TARIKH_MSHLOCH] = cc.Tarikh
WHERE 1=1  
AND Cast(SUBSTRING(cs.T_CHSHBONIT,1,4) as int) >= 2025
AND TM.QOD_SHOLCH <> TM.QOD_MQBL 

-------OPEN Orders----------------------------------------------------------------------------------
UNION ALL

 SELECT 
	'Delivery Note' as  'DocName'
	,'Item' AS 'LineType'
	,CONVERT(INT, CONVERT(VARCHAR, TM.QOD_MQBL)) AS 'AccountKey'
	,SUBSTRING(TARIKH_MSHLOCH,1,4) + '-' + SUBSTRING(TARIKH_MSHLOCH,5,2) + '-' + SUBSTRING(TARIKH_MSHLOCH,7,2) as 'Date'
	,CONVERT(INT, CONVERT(VARCHAR, TM.AISH_MCIROT)) AS 'AgentKey'
	,CONVERT(VARCHAR, TM.QOD_MOTSR)+'-'+CONVERT(VARCHAR, TM.QOD_MOTSR) AS 'ItemKey'
	,CAST(ROUND(CASE
	         WHEN TM.MTBE_SH = '$' THEN TM.MCHIR_ICH
	         ELSE TM.MCHIR_ICH * (1 / NULLIF(SM.NEW_SHER, 0))
         END, 2) AS FLOAT) AS 'UnitNetPriceUSD'
	,cast(ROUND(TM.MSHQL_NTO,2)AS FLOAT) as 'Quantity'
	,case
		when TM.ActionType = 11 then TM.MSHQL_NTO
		else 0 end
	as qty_cif
	,case
		when TM.ActionType = 1 then TM.MSHQL_NTO
		else 0 end
	as qty_fot
	,case
		when TM.ActionType = 1 then 'FOT'
		WHEN TM.ActionType = 11 then 'CIF'
		WHEN TM.ActionType = 12 then 'FOT Premium'
	else null 
	end as SalesType
	,0 AS 'AdditionalQuantity'
	,CAST(ROUND(CASE
	         WHEN TM.MTBE_SH = '$'
		     THEN TM.MCHIR_ICH * TM.MSHQL_NTO /*TM.CMOT_SHSOPQH*/
	         ELSE TM.MCHIR_ICH * TM.MSHQL_NTO /*TM.CMOT_SHSOPQH*/ * (1 / NULLIF(SM.NEW_SHER, 0))
         END, 2) AS FLOAT) AS 'LineTotalNet_USD'
	,CONVERT(INT, CONVERT(VARCHAR,SUBSTRING(T_ASPQH,1,4) + SUBSTRING(T_ASPQH,5,2))) AS YearMonth
	,TM.MS_TEODH as 'DeliveryNote'
	,CAST(SUBSTRING(TARIKH_MSHLOCH,1,4) + '-' + SUBSTRING(TARIKH_MSHLOCH,5,2) + '-' + SUBSTRING(TARIKH_MSHLOCH,7,2) as date) as 'DeliveryDate'
	,HZ.MSPR_HZMNH as 'OrderID'
	,TM.QOD_SHOLCH as 'SupplierWarehouse'
	,TM.ActionType							as 'ActionType'
	,CASE 
		WHEN TM.ActionType = 6 THEN G.AOPI_PEILOT
		ELSE act.ActionType
	END as 'ActionTypeDesc'
	,CASE
	WHEN TM.MCHIR_ICH = 0
		THEN '1'
	ELSE '0'
	END AS 'AdjustmentFlag'
	,CASE
		WHEN TM.MCHIR_ICH <> 0 THEN 'Sales'
		WHEN TM.MCHIR_ICH = 0 and G.AOPI_PEILOT = 'פחת' THEN 'Shortage'
		WHEN TM.MCHIR_ICH = 0 and G.AOPI_PEILOT = 'אחסון' THEN 'Storage'
		WHEN TM.MCHIR_ICH = 0 and G.AOPI_PEILOT NOT IN ('פחת','אחסון') then 'Swap'
	END AS 'QuantityCategory'
	,CASE
		WHEN TM.MCHIR_ICH = 0 AND W.QOD_GORM IS NOT NULL THEN G.AOPI_PEILOT
		WHEN TM.MCHIR_ICH = 0 AND W.QOD_GORM IS NULL     THEN 'החלפה'
		ELSE NULL
	END AS 'TransactionType'
FROM TEODOT_MSHLOCH TM
Left Join (SELECT distinct MS_T_MSHLOCH
			FROM CHSHBONIOT_SHOROT
		) CH
	on TM.MS_TEODH = CH.MS_T_MSHLOCH
Left Join (SELECT MS_HZMNH,MS_T_MSHLOCH
			FROM QISHOR_T_MSHLOCH_HZMNOT
		) HZT
	on TM.MS_TEODH = HZT.MS_T_MSHLOCH
Left Join HZMNOT HZ
	on HZ.MSPR_HZMNH = HZT.MS_HZMNH
LEFT JOIN CurrencyConvertion SM  -- reuse top-level CTE instead of repeating SHERI_MTBE inline
	ON SM.TARIKH = HZ.T_HZMNH
Left Join GORMIM G
	on TM.QOD_MQBL = G.QOD_GORM
Left Join (
			Select *
			From GORMIM
			Where EntityType Like N'%מקום אספקה%') W
	On W.QOD_GORM = TM.QOD_SHOLCH
left join TBLT_PEOLOT_HZMNH_T_MSHLOCH act
	on TM.ActionType = act.MS_AOPTSIH
WHERE
CH.MS_T_MSHLOCH is null
AND Cast(SUBSTRING(TARIKH_MSHLOCH,1,4) as int) >= 2025
AND STTOS in (0,1)
AND TM.PurchaseOrderType = 0
AND TM.QOD_SHOLCH <> TM.QOD_MQBL   -- exclude internal docs (same source and destination)
  )




,base_link as (
  SELECT distinct
        a.MS_TEODT_MCIRH AS DeliveryNote,
        b.MS_HZMNH AS PurchaseOrderID
    FROM QISHOR_RCSH_LMCIRH a
    LEFT JOIN QISHOR_T_MSHLOCH_HZMNOT b
        ON a.MS_TEODT_RCSH = b.MS_T_MSHLOCH

		)

-- Warehouse sales: delivery notes that have no entry in base_link are not linked to any
-- purchase order, meaning they originate from a warehouse (not import or exchange).
,WH_sales AS (
    SELECT
        s.DeliveryNote,
        s.DeliveryDate,
        FORMAT(s.DeliveryDate, 'yyyy-MM')                                           AS [Year-Month],
        s.AccountKey,
        s.AgentKey,
        s.ActionType,
        s.ActionTypeDesc,
        s.SupplierWarehouse,
        s.AdjustmentFlag,
        s.QuantityCategory,
        MAX(s.TransactionType)                                                      AS TransactionType,
        -- ItemKey, sale price, and SalesType come from the 'Item' line only
        MAX(CASE WHEN s.LineType = 'Item' THEN s.ItemKey        ELSE NULL END)      AS ItemKey,
        MAX(CASE WHEN s.LineType = 'Item' THEN s.SalesType      ELSE NULL END)      AS SalesType,
        MAX(CASE WHEN s.LineType = 'Item' THEN s.UnitNetPriceUSD ELSE NULL END)     AS UnitNetPriceUSD,
        -- Quantity = item qty only (excludes storage/additional-expense qty)
        SUM(CASE WHEN s.LineType = 'Item' THEN s.Quantity       ELSE 0   END)       AS Quantity,
        -- Total revenue = all lines combined (item + storage fee)
        SUM(s.LineTotalNet_USD)                                                     AS LineTotalNet_USD,
        -- Additional-line cost: the value of non-item lines (e.g. warehouse storage fee).
        -- Non-zero only when MultiLineFlag = 1; use this to compare WH additional costs vs other order types.
        SUM(CASE WHEN s.LineType <> 'Item' THEN s.LineTotalNet_USD ELSE 0 END)      AS AdditionalLineCost,
        SUM(s.AdditionalQuantity)                                                       AS AdditionalQuantity,
        -- 1 = delivery note had multiple lines (e.g. item + warehouse storage fee), 0 = single line
        CASE WHEN COUNT(*) > 1 THEN '1' ELSE '0' END                                   AS MultiLineFlag
    FROM sales s
    LEFT OUTER JOIN base_link bl ON bl.DeliveryNote = s.DeliveryNote
	WHERE s.SupplierWarehouse in (1144,1411,1367,1366,1289,1101,943)
    GROUP BY
        s.DeliveryNote, s.DeliveryDate,
        s.AccountKey, s.AgentKey,
        s.ActionType, s.ActionTypeDesc,
        s.SupplierWarehouse, 
        s.AdjustmentFlag, s.QuantityCategory
)

-- ============================================================
-- Branch 1: Import / Exchange orders — cost from P_costs
-- ============================================================
SELECT
	cast(s.DeliveryNote as varchar)																							AS DeliveryNote,
	s.LineType																												AS LineType,
	s.TransactionType																										AS TransactionType,
	s.QuantityCategory																										AS QuantityCategory,
	s.ActionTypeDesc																										AS ActionTypeDesc,
	PC.DocName																												AS Purchase_DocName,
	s.AdjustmentFlag																										AS AdjustmentFlag,
	case when s.rn = 1
		 then '1' else '0' end																								AS Qty_flag,
	'0'																														AS MultiLineFlag,
	'0'																														AS wh_flag,
	cast(s.PurchaseOrderID as varchar)																						AS PurchaseOrderID,
	cast(PC.SupplierKey as varchar)																							AS SupplierKey,
	cast(s.AccountKey as varchar)																							AS AccountKey,
	cast(s.AgentKey as varchar)																								AS AgentKey,
	cast(s.ItemKey as varchar)																								AS ItemKey,
	cast(PC.boat as varchar)																								AS ShipID,
	FORMAT(PC.ValueDate, 'yyyy-MM')																							AS [Year-Month],
	PC.ValueDate																											AS ValueDate,
	s.DeliveryDate																											AS DeliveryDate,
	case when s.SalesType is null then s.QuantityCategory
		 else s.SalesType end																								AS [Price Term],
	s.Quantity																												AS Quantity,
	case when s.rn = 1
	then PC.orderquantity else 0 end																							AS PurchaseQuantity,
	s.LineTotalNet_USD																										AS LineTotalNet_USD,
	NULL																													AS Item_Price,
	NULL																													AS Storage_Price,
	CASE WHEN s.AdjustmentFlag <> 1
		 THEN CAST(ROUND(s.LineTotalNet_USD / NULLIF(s.Quantity, 0), 2) AS FLOAT)
		 ELSE NULL END																										AS Total_Price,
	s.UnitNetPriceUSD																										AS UnitNetPriceUSD,
	case when s.rn = 1
	then PC.Cif_price else 0 end																							AS CIF_Purchase,
	case when s.rn = 1
	then PC.[demurrage / Despatch] else 0 end																				AS [demurrage / Despatch],
	CASE WHEN s.rn = 1 THEN PC.[Other_Expenses]     ELSE 0 END																AS [Other_Expenses],
	CASE WHEN s.rn = 1 THEN PC.Shortage            ELSE 0 END																AS Shortage,
	CASE WHEN s.rn = 1 THEN
		CAST(ROUND(PC.DischargeCosts /
			NULLIF(PC.orderquantity, 0), 2) AS FLOAT)
	ELSE 0 END																												AS DischargeCost,
	CASE WHEN s.rn = 1 THEN
		CAST(ROUND(PC.Cif_price + PC.[demurrage / Despatch] + (PC.DischargeCosts /
			NULLIF(PC.orderquantity, 0)), 2) AS FLOAT)
	ELSE 0 END																												AS FOT_Purchase,
	null																													AS Total_WH_cost,
	CAST(ROUND(CASE
		WHEN s.SalesType = 'CIF'                   AND s.LineType = 'Item'
			THEN (s.LineTotalNet_USD / NULLIF(s.Quantity, 0)) - PC.Cif_price
		WHEN s.SalesType IN ('FOT', 'FOT Premium') AND s.LineType = 'Item'
			THEN (s.LineTotalNet_USD / NULLIF(s.Quantity, 0)) - (PC.Cif_price + PC.[demurrage / Despatch] + (PC.DischargeCosts /
				 NULLIF(PC.orderquantity, 0)))
		ELSE 0
	END, 2) AS FLOAT)																										AS Gain,
	CAST(ROUND(CASE
		WHEN s.SalesType = 'CIF'                   AND s.LineType = 'Item'
			THEN ((s.LineTotalNet_USD / NULLIF(s.Quantity, 0)) - PC.Cif_price) * s.Quantity
		WHEN s.SalesType IN ('FOT', 'FOT Premium') AND s.LineType = 'Item'
			THEN ((s.LineTotalNet_USD / NULLIF(s.Quantity, 0)) - (PC.Cif_price + PC.[demurrage / Despatch] + (PC.DischargeCosts /
				 NULLIF(PC.orderquantity, 0)))) * s.Quantity
		ELSE 0
	END, 2) AS FLOAT)																										AS TotalGain,
	NULL																													AS AdditionalLineCost
FROM (
    SELECT s.*,
           bl.PurchaseOrderID,
           ROW_NUMBER() OVER (PARTITION BY bl.PurchaseOrderID ORDER BY s.DeliveryNote ASC) AS rn
    FROM sales s
    INNER JOIN base_link bl ON bl.DeliveryNote = s.DeliveryNote
) s
LEFT JOIN  P_costs PC   ON PC.PurchaseOrderID = CAST(s.PurchaseOrderID AS VARCHAR(30))
WHERE PC.ValueDate IS NOT NULL

UNION ALL

-- ============================================================
-- Branch 2: Warehouse orders — cost from inv (LastCFPrice)
-- ============================================================
SELECT
    CAST(s.DeliveryNote AS VARCHAR)																							AS DeliveryNote,
	'Item'																													AS LineType,
	s.TransactionType																										AS [TransactionType],
	s.QuantityCategory																										AS [QuantityCategory],
    s.ActionTypeDesc																										AS [ActionTypeDesc],
    'Warehouse'																												AS Purchase_DocName,
	s.AdjustmentFlag																										AS [AdjustmentFlag],
	'0'																														AS Qty_flag,
	s.MultiLineFlag																											AS [MultiLineFlag],
	case when row_number() over
	(partition by s.SupplierWarehouse, FORMAT(s.DeliveryDate, 'yyyy-MM'), s.ItemKey
	order by s.DeliveryNote asc) = 1
         then '1' else '0' end																								AS wh_flag,
    CAST(s.SupplierWarehouse AS VARCHAR(10)) + '_' +
	FORMAT(s.DeliveryDate, 'yyyyMM') + '_' + CAST(s.ItemKey AS VARCHAR)														AS PurchaseOrderID,
    CAST(s.SupplierWarehouse AS VARCHAR)																					AS SupplierKey,
	CAST(s.AccountKey AS VARCHAR)																							AS AccountKey,
    CAST(s.AgentKey AS VARCHAR)																								AS AgentKey,
    CAST(s.ItemKey AS VARCHAR)																								AS ItemKey,
    NULL																													AS ShipID,
	FORMAT(s.DeliveryDate, 'yyyy-MM')																						AS [Year-Month],
    CAST(FORMAT(s.DeliveryDate, 'yyyy-MM') + '-01' AS DATE)																	AS ValueDate,
    s.DeliveryDate																											AS [DeliveryDate],			
    CASE WHEN s.SalesType IS NULL THEN s.QuantityCategory
         ELSE s.SalesType END																								AS [Price Term],
	s.Quantity																												AS [Quantity],
	s.Quantity																												AS PurchaseQuantity,
    s.LineTotalNet_USD																										AS [LineTotalNet_USD],
    CASE WHEN s.Quantity > 0
         THEN CAST(ROUND((s.LineTotalNet_USD - s.AdditionalLineCost) / NULLIF(s.Quantity, 0), 2) AS FLOAT)
         ELSE NULL END                                                                                                      AS Item_Price,
    CASE WHEN s.AdditionalQuantity > 0
         THEN CAST(ROUND(s.AdditionalLineCost / NULLIF(s.AdditionalQuantity, 0), 2) AS FLOAT)
         ELSE NULL END                                                                                                      AS Storage_Price,
    CASE WHEN s.AdjustmentFlag <> 1
         THEN CAST(ROUND(
             (s.LineTotalNet_USD - s.AdditionalLineCost) / NULLIF(s.Quantity, 0) +
             ISNULL(s.AdditionalLineCost / NULLIF(s.AdditionalQuantity, 0), 0),
             2) AS FLOAT)
         ELSE NULL END                                                                                                      AS Total_Price,
    s.UnitNetPriceUSD																										AS [UnitNetPriceUSD],
    NULL																													AS CIF_Purchase,  -- no CIF concept for warehouse
    NULL																													AS [demurrage / Despatch],
    NULL																													AS [Other_Expenses],
    NULL																													AS Shortage,
    NULL																													AS DischargeCost, 
    inv.WH_Price																											AS FOT_Purchase,
	16 + inv.WH_Price																										AS Total_WH_cost,
    CASE WHEN s.AdjustmentFlag <> 1
         THEN CAST(ROUND((s.LineTotalNet_USD / NULLIF(s.Quantity, 0)) - (16 + inv.WH_Price), 2) AS FLOAT)
         ELSE 0 END																											AS Gain,
    CASE WHEN s.AdjustmentFlag <> 1
         THEN CAST(ROUND((s.LineTotalNet_USD / NULLIF(s.Quantity, 0)) - (16 + inv.WH_Price), 2) AS FLOAT) * s.Quantity
         ELSE 0 END																											AS TotalGain,
    s.AdditionalLineCost																									AS [AdditionalLineCost] --wh charge cost
FROM WH_sales s
LEFT JOIN inv
    ON  inv.ItemKey = s.ItemKey
    AND FORMAT(inv.[Date], 'yyyyMM') = FORMAT(s.DeliveryDate, 'yyyyMM')
GO
SET STATISTICS IO, TIME OFF;
GO
-- factGain (current) - extracted from TMDL by extract_queries.py
-- Run on STG only. Before running: Query > Query Options > Results > Grid >
-- tick 'Discard results after execution', so SSMS does not render the rows.
PRINT '===== factGain | current =====';
SET STATISTICS IO, TIME ON;
GO

-- factGain - materialized version (see sql/incident_2026-10/fix/build_materialized.py).
-- Same logic as the CTE version; CTEs used more than once are computed once into temp tables.
SET NOCOUNT ON;
IF OBJECT_ID('tempdb..#exchange_movements') IS NOT NULL DROP TABLE #exchange_movements;
IF OBJECT_ID('tempdb..#purchase_orders') IS NOT NULL DROP TABLE #purchase_orders;
IF OBJECT_ID('tempdb..#P_costs') IS NOT NULL DROP TABLE #P_costs;
DECLARE @CutoffDate DATE = '2024-01-01';

-- ======================================================================
-- Step: materialize exchange_movements
;WITH CurrencyConvertion AS (
SELECT *, 
         CASE
         	WHEN sher = 0
         	THEN FIRST_VALUE(sher) OVER (PARTITION BY value_partition ORDER BY Tarikh) 
         	ELSE sher
         END AS new_sher
         ,CASE
         	WHEN SHER_EURO = 0
         	THEN FIRST_VALUE(SHER_EURO) OVER (PARTITION BY value_partitionEuro ORDER BY Tarikh) 
         	ELSE  SHER_EURO
         END AS new_sherEuro
 FROM (
          SELECT *
 ,SUM(CASE WHEN sher=0 THEN 0 ELSE 1 END) OVER (ORDER BY tarikh ) AS value_partition
 ,SUM(CASE WHEN SHER_EURO=0 THEN 0 ELSE 1 END) OVER (ORDER BY tarikh ) AS value_partitionEuro
          FROM SHERI_MTBE
 ) m
)

--------------------------------------------------------------- the below part should be a view is the database ----------------------------------------------------
,
totals_raw AS (
    -- Step 1: per-row calculations
    SELECT
        CONCAT(
            CAST(CONVERT(BIGINT, POL.POL_OrderID) AS VARCHAR(20)),
            CAST(POL.POL_LineID AS VARCHAR(10))
        ) AS PurchaseOrderID,

        CONVERT(VARCHAR, HS.QOD_MOTSR) + '-' + CONVERT(VARCHAR, HS.QOD_MOTSR) AS ItemKey,

        -- PNL classification
        CASE
            WHEN HST.QOD_SHROT IN (5, 19, 30, 4)
              OR HST.QOD_SHROT IS NULL
                THEN 999
            ELSE HST.QOD_SHROT
        END AS PNLKey,

        -- Order quantity (only main item rows)
        CASE
            WHEN HS.QOD_SHROT = 0 THEN HS.CMOT
            ELSE 0
        END AS OrderQuantity,

        -- Line total in USD (exactly כמו הקטע ששלחת)
        CASE
            WHEN HS.MTBE = '$' THEN HS.MCHIR_ICH * HS.CMOT
            WHEN HS.MTBE = 'Eur' THEN HS.MCHIR_ICH * HS.CMOT * (SM.NEW_SHEREURO / NULLIF(SM.NEW_SHER, 0))
            ELSE HS.MCHIR_ICH * HS.CMOT * (
                    1 / CASE WHEN HC.SHER_MTBE = 0 THEN 1 ELSE HC.SHER_MTBE END
                 )
        END AS LineTotalNetUSD
    FROM HOTSAOT_COTROT HC
    LEFT JOIN HOTSAOT_SHOROT HS
        ON HC.NOMRTOR = HS.NOMRTOR
    LEFT JOIN PurchaseOrderLines POL
        ON CONCAT(
               CAST(CONVERT(BIGINT, POL.POL_OrderID) AS VARCHAR(20)),
               CAST(POL.POL_LineID AS VARCHAR(10))
           ) = CAST(HS.MS_MSMKH_QSHOR AS VARCHAR(30))
    LEFT JOIN HOTSAOT_SHROTIM_New HST
        ON HS.QOD_SHROT = HST.QOD_SHROT
    LEFT JOIN CurrencyConvertion SM
        ON SM.TARIKH = HC.T_ERKH
    WHERE 1 = 1
      AND CAST(SUBSTRING(HC.T_MSMKH, 1, 4) AS INT) >= 2018
      AND CAST(SUBSTRING(HC.T_MSMKH, 1, 4) AS INT) <= YEAR(GETDATE())
      AND HS.QOD_SHROT NOT IN (14)
)
,
totals AS (
    -- Step 2: aggregate like the DAX measure. NOTE: UnitNetPriceUSD here is a blended average
    -- (commodity + freight/demurrage/discharge all summed together) — it is NOT the true CIF
    -- price. It's used only to identify/rank candidate import matches in exchange_priced; the
    -- actual CIF/demurrage/discharge values for a matched import are read from P_costs later,
    -- in the final SELECT, once the matched import's PurchaseOrderID is known (see purchase_orders'
    -- Swap branch / MatchedImportPO).
    SELECT
        PurchaseOrderID,
        ItemKey,
        999 as PNLKey,
        SUM(LineTotalNetUSD) AS LineTotalNetUSD,       -- same as [Total Expenses USD]
        SUM(OrderQuantity)   AS OrderQuantity,     -- same as [Total Order Quantity (Hzmnot)]
        CAST(ROUND(SUM(LineTotalNetUSD) / NULLIF(SUM(OrderQuantity), 0), 2) AS FLOAT) AS UnitNetPriceUSD  -- Avg Price USD (Expenses)
    FROM totals_raw
    GROUP BY
        PurchaseOrderID,
        ItemKey
)

-- exchange_movements: merges former 'main' + 'base' — raw free shipments enriched with purchase cost
,
exchange_movements AS (
    SELECT
        TM.QOD_SHOLCH  AS DeliveredFrom,
        W.SHM_GORM     AS DeliveredFromName,
        ISNULL(b.MS_HZMNH, bb.MS_HZMNH) AS PurchaseOrderID,
        CASE
            WHEN ISNULL(b.MS_HZMNH, bb.MS_HZMNH) LIKE '2000%' THEN 'P' -- Purchase order
            ELSE 'E'                                                     -- Expense / other
        END AS Order_Type,
        CONVERT(VARCHAR, TM.QOD_MOTSR) + '-' + CONVERT(VARCHAR, TM.QOD_MOTSR) AS ItemKey,
        SUM(TM.MSHQL_NTO) AS qty_loaned,
        G.QOD_GORM     AS DeliveredTo,
        G.SHM_GORM     AS DeliveredToName,
        SUBSTRING(TARIKH_MSHLOCH, 1, 4) + '-' + SUBSTRING(TARIKH_MSHLOCH, 5, 2) AS [Date],
        -- price columns from totals (previously joined in the separate 'base' CTE) — a blended
        -- average, used only to identify/rank the best candidate import match below. The Swap
        -- branch does NOT use this as its final price — it reads the matched import's true
        -- Cif_price/demurrage/discharge from P_costs directly, downstream in the final SELECT,
        -- keyed on Purchase (the matched import's own PurchaseOrderID, carried through below).
        t.UnitNetPriceUSD,
        t.LineTotalNetUSD,
        t.OrderQuantity
    FROM TEODOT_MSHLOCH TM
    LEFT JOIN GORMIM G                   ON TM.QOD_MQBL        = G.QOD_GORM
    LEFT JOIN GORMIM W                   ON TM.QOD_SHOLCH       = W.QOD_GORM
    LEFT JOIN QISHOR_RCSH_LMCIRH a       ON a.MS_TEODT_MCIRH   = TM.MS_TEODH
    LEFT JOIN QISHOR_T_MSHLOCH_HZMNOT b  ON a.MS_TEODT_RCSH    = b.MS_T_MSHLOCH
    LEFT JOIN QISHOR_T_MSHLOCH_HZMNOT bb ON bb.MS_T_MSHLOCH    = TM.MS_TEODH
    LEFT JOIN (
        SELECT PurchaseOrderID, ItemKey, UnitNetPriceUSD, LineTotalNetUSD, OrderQuantity
        FROM totals
        WHERE PNLKey = 999
          AND OrderQuantity <> 0
    ) t ON ISNULL(b.MS_HZMNH, bb.MS_HZMNH) = t.PurchaseOrderID
    WHERE --TM.MCHIR_ICH = 0                         -- Only free/loaned shipments
      G.AOPI_PEILOT NOT IN (N'אחסון')                -- Exclude storage
      -- Date cutoff only applies to swap/loan movements (Order_Type = 'E'); candidate imports
      -- (Order_Type = 'P', resolved PO LIKE '2000%') must never be cut off by this, or a swap
      -- can lose its true matching import just because the import's movement row predates the
      -- cutoff. No upper bound here — a future import is still a valid match candidate.
      AND (ISNULL(b.MS_HZMNH, bb.MS_HZMNH) LIKE '2000%'
           OR TRY_CONVERT(DATE, SUBSTRING(TARIKH_MSHLOCH, 1, 4) + '-' + SUBSTRING(TARIKH_MSHLOCH, 5, 2) + '-' + SUBSTRING(TARIKH_MSHLOCH, 7, 2)) >= @CutoffDate)
    GROUP BY
        SUBSTRING(TARIKH_MSHLOCH, 1, 4) + '-' + SUBSTRING(TARIKH_MSHLOCH, 5, 2),
        TM.QOD_SHOLCH, W.SHM_GORM,
        b.MS_HZMNH, bb.MS_HZMNH,
        CONVERT(VARCHAR, TM.QOD_MOTSR) + '-' + CONVERT(VARCHAR, TM.QOD_MOTSR),
        G.QOD_GORM, G.SHM_GORM,
        t.UnitNetPriceUSD, t.LineTotalNetUSD, t.OrderQuantity
)
SELECT * INTO #exchange_movements FROM exchange_movements;

-- ======================================================================
-- Step: materialize purchase_orders
;WITH CurrencyConvertion AS (
SELECT *, 
         CASE
         	WHEN sher = 0
         	THEN FIRST_VALUE(sher) OVER (PARTITION BY value_partition ORDER BY Tarikh) 
         	ELSE sher
         END AS new_sher
         ,CASE
         	WHEN SHER_EURO = 0
         	THEN FIRST_VALUE(SHER_EURO) OVER (PARTITION BY value_partitionEuro ORDER BY Tarikh) 
         	ELSE  SHER_EURO
         END AS new_sherEuro
 FROM (
          SELECT *
 ,SUM(CASE WHEN sher=0 THEN 0 ELSE 1 END) OVER (ORDER BY tarikh ) AS value_partition
 ,SUM(CASE WHEN SHER_EURO=0 THEN 0 ELSE 1 END) OVER (ORDER BY tarikh ) AS value_partitionEuro
          FROM SHERI_MTBE
 ) m
)

--------------------------------------------------------------- the below part should be a view is the database ----------------------------------------------------
,
exchange_p_orders AS (
    -- P-type movements only: the original purchases that exchanges are matched against
    SELECT
        DeliveredFrom,
        DeliveredFromName,
        PurchaseOrderID,
        ItemKey,
        SUM(qty_loaned)        AS quantity,
        DeliveredTo,
        DeliveredToName,
        [Date]                 AS Purchase_Date,
        MAX(UnitNetPriceUSD)   AS max_unit_price,
        MAX(LineTotalNetUSD)   AS max_LineTotalNetUSD,
        MAX(OrderQuantity)     AS max_OrderQuantity
    FROM #exchange_movements
    WHERE Order_Type = 'P'
    GROUP BY
        DeliveredFrom, DeliveredFromName,
        PurchaseOrderID, ItemKey,
        DeliveredTo, DeliveredToName,
        [Date]
)

-- exchange_priced: merges former 'final' + 'final2' — ranks and keeps only the best purchase match.
-- `Purchase` is the matched import's own PurchaseOrderID — this is what the Swap branch carries
-- forward to join P_costs directly for the true Cif_price/demurrage/discharge, downstream.
,
exchange_priced AS (
    SELECT
            b.DeliveredFrom,
            b.DeliveredFromName,
            b.PurchaseOrderID  AS Exchange_order,
            b.[Date]           AS Exchange_Order_Date,
            b.ItemKey,
            b.qty_loaned       AS Qty_Sold,
            p.PurchaseOrderID  AS Purchase,
            p.Purchase_Date,
            p.max_unit_price   AS UnitNetPriceUSD,
            p.max_LineTotalNetUSD AS LineTotalNetUSD,
            p.max_OrderQuantity   AS OrderQuantity,
            -- Only surface the ship when the matched import actually has cost data (p.max_LineTotalNetUSD
            -- not null) — a PO can be linked (ship_sub joins on PurchaseOrderID alone) before its expense
            -- documents are posted. Without this, the boat shows with no CIF/FOT numbers behind it, which
            -- reads as a data error rather than "costs not posted yet".
            CASE WHEN p.max_LineTotalNetUSD IS NOT NULL THEN ship_sub.ShipID ELSE NULL END AS ShipID,
            -- Matching rule: prefer the nearest import within the past 3 months (inclusive).
            -- Only when none exists in that window do we look ahead to the nearest future
            -- import (no limit on how far forward). An import older than 3 months in the past
            -- is never used, even if it's the only candidate — the swap gets no price instead
            -- (enforced by the eligibility filter in the join below, not just by ranking, so a
            -- lone too-old candidate can't win rn=1 by default).
            ROW_NUMBER() OVER (
                PARTITION BY b.DeliveredFrom, b.PurchaseOrderID, b.ItemKey, b.[Date]
                ORDER BY
                    CASE WHEN CAST(p.Purchase_Date + '-01' AS DATE) <= CAST(b.[Date] + '-01' AS DATE) THEN 0 ELSE 1 END,
                    ABS(DATEDIFF(MONTH, CAST(b.[Date] + '-01' AS DATE), CAST(p.Purchase_Date + '-01' AS DATE))) ASC,
                    p.PurchaseOrderID DESC
            ) AS rn
        FROM #exchange_movements b
        LEFT JOIN exchange_p_orders p
            ON  b.DeliveredFrom = p.DeliveredTo
            AND b.ItemKey       = p.ItemKey
            -- Eligibility: past import must be within 3 months (inclusive); future imports are
            -- eligible at any distance. This is a hard filter, not just a tie-break — an import
            -- older than 3 months is excluded from the join entirely, so it can never surface as
            -- rn=1 even when it's the only candidate for this DeliveredFrom/ItemKey pair.
            AND (
                    DATEDIFF(MONTH, CAST(p.Purchase_Date + '-01' AS DATE), CAST(b.[Date] + '-01' AS DATE)) BETWEEN 0 AND 3
                 OR CAST(p.Purchase_Date + '-01' AS DATE) > CAST(b.[Date] + '-01' AS DATE)
                )
        -- Look up the ship that delivered the related purchase order.
        -- p.PurchaseOrderID = CONCAT(POL_OrderID, POL_LineID) — same format as totals_raw.
        -- Must include POL_LineID in the key, otherwise it never matches.
        LEFT JOIN (
            SELECT
                CONCAT(
                    CAST(CONVERT(BIGINT, POL.POL_OrderID) AS VARCHAR(20)),
                    CAST(POL.POL_LineID AS VARCHAR(10))
                )              AS PurchaseOrderID,
                MAX(sl.ShipID) AS ShipID
            FROM PurchaseOrderLines POL
            JOIN ShipsArrivals sa ON POL.POL_ShipArrivalID = sa.SA_ID
            JOIN ShipList      sl ON sa.SA_ShipID          = sl.ShipID
            GROUP BY POL.POL_OrderID, POL.POL_LineID
        ) ship_sub ON ship_sub.PurchaseOrderID = CAST(p.PurchaseOrderID AS VARCHAR(30))
)

-- Swap_RootSupplier: a swap order's real supplier, independent of exchange_movements' matching
-- logic above. Goods often pass through an internal distribution/emergency warehouse before
-- reaching the customer (supplier -> warehouse -> customer(s)); exchange_movements' raw
-- DeliveredFrom can land on that intermediate warehouse instead of the true supplier. This CTE
-- finds the root of the chain at the raw per-transaction grain (before exchange_movements'
-- month/from/to aggregation folds legs together): the DeliveredFrom that never appears as
-- another row's DeliveredTo for the same order. Used ONLY to override SupplierKey below — the
-- Cif_price/discharge/demurrage matching in exchange_movements/exchange_p_orders/exchange_priced
-- is untouched.
,
Swap_Moves AS (
    SELECT
        ISNULL(b.MS_HZMNH, bb.MS_HZMNH) AS OrderID,
        TM.QOD_SHOLCH  AS DeliveredFrom,
        TM.QOD_MQBL    AS DeliveredTo
    FROM TEODOT_MSHLOCH TM
    LEFT JOIN GORMIM G                   ON TM.QOD_MQBL       = G.QOD_GORM
    LEFT JOIN QISHOR_RCSH_LMCIRH a       ON a.MS_TEODT_MCIRH  = TM.MS_TEODH
    LEFT JOIN QISHOR_T_MSHLOCH_HZMNOT b  ON a.MS_TEODT_RCSH   = b.MS_T_MSHLOCH
    LEFT JOIN QISHOR_T_MSHLOCH_HZMNOT bb ON bb.MS_T_MSHLOCH   = TM.MS_TEODH
    WHERE G.AOPI_PEILOT NOT IN (N'אחסון')
      AND ISNULL(b.MS_HZMNH, bb.MS_HZMNH) IS NOT NULL
)
,
Swap_RootSupplier AS (
    SELECT
        OrderID,
        -- MIN() is a deterministic tie-break for the rare order with more than one independent
        -- root supplier; normally there's exactly one.
        MIN(DeliveredFrom) AS RootSupplierKey
    FROM Swap_Moves m
    WHERE NOT EXISTS (
        SELECT 1 FROM Swap_Moves m2
        WHERE m2.OrderID = m.OrderID AND m2.DeliveredTo = m.DeliveredFrom
    )
    GROUP BY OrderID
)

-----------------------------------------------------------------------------------------------------------------------------------------------
,
purchase_orders AS (

----Invoice--
SELECT
	 CAST(CCS.HZMNT_RCSH AS VARCHAR)			AS PurchaseOrderID,
     'Invoice'									AS DocName,
     NULL										AS SupplierKey,
     CAST(SUBSTRING(CCS.T_CHSHBONIT,1,4) + '-' + SUBSTRING(CCS.T_CHSHBONIT,5,2) + '-' + SUBSTRING(CCS.T_CHSHBONIT,7,2) AS DATE) AS [Value Date],
     CAST(CONVERT(VARCHAR, POL_ProductID) AS VARCHAR) + '-' + CAST(CONVERT(VARCHAR, M.ServiceCode) AS VARCHAR) + 'S' AS ItemKey,
     CAST(ROUND(CCS.MCHIR_ICH_LLA_ME_M / NULLIF(CASE WHEN SHER_LCHISHOB <> 0 THEN SHER_LCHISHOB ELSE CC2.new_sher END, 0), 2) AS FLOAT) * -1  AS UnitNetPriceUSD,
     CCS.MSHQL_NTO                   AS Quantity,
     CASE WHEN CCS.QOD_MOTSR = 0 THEN CCS.MSHQL_NTO ELSE 0 END AS OrderQuantity,
     HST.QOD_SHROT                           AS PNLKey,
	 HST.PNL as [PNL Code],
     CAST(ROUND(CCS.CMOT * (CCS.MCHIR_ICH_LLA_ME_M / NULLIF(CASE WHEN SHER_LCHISHOB <> 0 THEN SHER_LCHISHOB ELSE CC2.new_sher END, 0)), 2) AS FLOAT) * -1 AS LineTotalNetUSD,
     CONVERT(INT, CONVERT(VARCHAR, SUBSTRING(CCS.T_CHSHBONIT,1,4) + SUBSTRING(CCS.T_CHSHBONIT,5,2))) AS YearMonth,
	 null as ShipID,
    'Invoice'                                AS DocType,
	CASE WHEN SHER_LCHISHOB <> 0 THEN SHER_LCHISHOB ELSE CC2.new_sher END as [NEW_SHER],
	NULL									AS MatchedImportPO  -- only Swap rows have this
FROM [dbo].[CHIOBI_CHOTS_COTROT] CC
LEFT JOIN [dbo].[CHIOBI_CHOTS_SHOROT] CCS
       ON CC.MS_CHSHBONIT = CCS.MS_CHSHBONIT
LEFT JOIN CurrencyConvertion CC2
       ON CCS.[TARIKH_MSHLOCH] = CC2.Tarikh
LEFT JOIN (select DISTINCT
			POL_SQL_POID, POL_ProductID
			from PurchaseOrderLines POL	) POL
		ON CCS.HZMNT_RCSH = POL.POL_SQL_POID
LEFT JOIN MOTSRIM M
	ON CCS.QOD_MOTSR = M.QOD_MOTSR
LEFT JOIN HOTSAOT_SHROTIM_New HST 
	ON M.ServiceCode = HST.QOD_SHROT
	where CAST(SUBSTRING(CCS.T_CHSHBONIT,1,4) + '-' + SUBSTRING(CCS.T_CHSHBONIT,5,2) + '-' + SUBSTRING(CCS.T_CHSHBONIT,7,2) AS DATE) >= @CutoffDate

UNION ALL
	------Import--------
SELECT

		CONCAT(
			CAST(CONVERT(BIGINT, POL.POL_OrderID) AS VARCHAR(20)),
			CAST(POL.POL_LineID AS VARCHAR(10))
		 )	as 'PurchaseOrderID'
		,'Import' AS 'DocName'  -- was: 'Order Expenses'
		,CAST(
		  MAX(
			CASE WHEN HS.QOD_SHROT = 0
				 THEN CONVERT(INT, CONVERT(VARCHAR, HC.QOD_SPQ))
			END
		  ) OVER (PARTITION BY HS.MS_MSMKH_QSHOR)
			AS VARCHAR)	 AS 'SupplierKey'
		,CASE 
			WHEN HS.MS_MSMKH_QSHOR = 0 
			  THEN CONVERT(date, HC.T_ERKH, 112)
			ELSE
			  MAX(
				CASE WHEN HS.QOD_SHROT = 0 
					 THEN CONVERT(date, HC.T_ERKH, 112) 
				END
			  ) OVER (
				PARTITION BY 
				  CASE 
					WHEN HS.MS_MSMKH_QSHOR = 0 
					  THEN HZ.MSPR_HZMNH 
					ELSE HS.MS_MSMKH_QSHOR 
				  END
			  )
		  END AS 'Value Date'
		,CASE
			WHEN  HST.QOD_SHROT IS NULL OR HS.QOD_SHROT IN (5, 19, 30, 4) THEN cast(CONVERT(INT, CONVERT(VARCHAR,HS.QOD_MOTSR)) as varchar)+ '-' + cast(CONVERT(INT, CONVERT(VARCHAR,HS.QOD_MOTSR)) as varchar) -- העמסת עליות הובלה והפרש מחיר על המוצר
			ELSE cast(CONVERT(INT, CONVERT(VARCHAR,HS.QOD_MOTSR)) as varchar)+ '-' + cast(CONVERT(INT, CONVERT(VARCHAR,HST.QOD_SHROT)) as varchar)+'S' 
			END		AS 'ItemKey'

		 ,CASE
			WHEN HST.QOD_SHROT IS NOT NULL THEN
				CASE
					WHEN HS.MTBE = '$' THEN
						CAST(ROUND(HS.MCHIR_ICH / NULLIF(POL.POL_FinalWeightReceived, 0), 2) AS FLOAT)
					WHEN HS.MTBE = 'Eur' THEN
						CAST(ROUND(
							HS.MCHIR_ICH * (SM.NEW_SHEREURO / NULLIF(SM.NEW_SHER, 0)) / NULLIF(POL.POL_FinalWeightReceived, 0)
						, 2) AS FLOAT)
					ELSE
						CAST(ROUND(
							HS.MCHIR_ICH * (1 / NULLIF(HC.SHER_MTBE, 0)) / NULLIF(POL.POL_FinalWeightReceived, 0)
						, 2) AS FLOAT)
				END
			ELSE
				CASE
					WHEN HS.MTBE = '$' THEN CAST(ROUND(HS.MCHIR_ICH, 2) AS FLOAT)
					WHEN HS.MTBE = 'Eur' THEN
						CAST(ROUND(
							HS.MCHIR_ICH * (SM.NEW_SHEREURO / NULLIF(SM.NEW_SHER, 0))
						, 2) AS FLOAT)
					ELSE
						CAST(ROUND(
							HS.MCHIR_ICH * (1 / NULLIF(HC.SHER_MTBE, 0))
						, 2) AS FLOAT)
				END
		END AS 'UnitNetPriceUSD'
		,HS.CMOT AS 'Quantity'
		,CASE WHEN HS.QOD_SHROT = 0 then HS.CMOT
				ELSE 0
				END									AS 'OrderQuantity'
		,CASE 
			WHEN HST.QOD_SHROT IN (5, 19, 30, 4,18) OR HST.QOD_SHROT IS NULL 
			THEN 999
			ELSE HST.QOD_SHROT
		END											AS 'PNLKey' ----------  העמסת עליות הובלה על המוצר והפרש מחיר
			,case when HST.QOD_SHROT IN (5, 19, 30, 4,18) OR HST.QOD_SHROT IS NULL  then 1010 
			else HST.PNL end as [PNL Code]
			,CAST(ROUND(CASE
	         WHEN HS.MTBE = '$' THEN HS.MCHIR_ICH * HS.CMOT
			 WHEN HS.MTBE = 'Eur' THEN HS.MCHIR_ICH * HS.CMOT * (SM.NEW_SHEREURO / NULLIF(SM.NEW_SHER, 0))
	         ELSE HS.MCHIR_ICH * HS.CMOT * (1 / CASE WHEN HC.SHER_MTBE = 0 THEN 1 ELSE HC.SHER_MTBE END)
         END, 2) AS FLOAT) AS 'LineTotalNetUSD'
		,CONVERT(INT, CONVERT(VARCHAR,SUBSTRING(HS.T_ERKH,1,4) + SUBSTRING(HS.T_ERKH,5,2))) AS YearMonth
		,sl.ShipID
		,CASE 
		    WHEN HS.QOD_SHROT IN (5, 19, 30, 20, 4) THEN N'סחורה'
		    ELSE HC.SOG_MSMKH
		END												as DocType
		,SM.NEW_SHER
		,NULL											AS MatchedImportPO  -- only Swap rows have this
FROM HOTSAOT_COTROT HC
LEFT JOIN HOTSAOT_SHOROT HS ON HC.NOMRTOR = HS.NOMRTOR
LEFT JOIN PurchaseOrderLines POL ON CONCAT(
										CAST(CONVERT(BIGINT, POL.POL_OrderID) AS VARCHAR(20)),
										CAST(POL.POL_LineID AS VARCHAR(10))
									)	
										= CAST(HS.MS_MSMKH_QSHOR AS VARCHAR(30))
LEFT JOIN HZMNOT HZ ON (HS.MS_MSMKH_QSHOR = HZ.MSPR_HZMNH)
LEFT JOIN HOTSAOT_SHROTIM_New HST ON HS.QOD_SHROT = HST.QOD_SHROT
LEFT JOIN ShipsArrivals sa ON POL.POL_ShipArrivalID = sa.SA_ID
LEFT JOIN ShipList sl ON sa.SA_ShipID = sl.ShipID
LEFT JOIN PurchaseOrder PO ON POL.POL_OrderID = PO.PO_OrderID
LEFT JOIN CurrencyConvertion SM  ON SM.TARIKH=HC.T_ERKH

WHERE 1=1
and Cast(SUBSTRING(HC.T_MSMKH,1,4) as int) >=2018 and Cast(SUBSTRING(HC.T_MSMKH,1,4) as int) <= YEAR(GETDATE())
and HS.QOD_SHROT NOT IN (14)
and CONCAT(CAST(CONVERT(BIGINT, POL.POL_OrderID) AS VARCHAR(20)),CAST(POL.POL_LineID AS VARCHAR(10))) <> ' '
and  cast( HC.T_ERKH as date) >= @CutoffDate

UNION ALL

-----Exchange----
-- Single row per swap PO, same shape as before. UnitNetPriceUSD/LineTotalNetUSD here are only
-- the blended totals-based price (used historically for this branch) — they are NOT the swap's
-- final cost basis anymore. The final SELECT instead joins P_costs a second time, keyed on
-- MatchedImportPO (t.Purchase — the matched import's own PurchaseOrderID), to read that import's
-- true, already-computed Cif_price/demurrage/discharge directly — no recalculation, so it can
-- never drift from what P_costs reports for that import elsewhere in the model.
SELECT
    CAST(HZ.MSPR_HZMNH AS VARCHAR)                                      AS PurchaseOrderID,
    'Swap'                                                          AS DocName,  -- was: 'Orders'
    ISNULL(rs.RootSupplierKey, t.DeliveredFrom)                        AS SupplierKey,
    CAST(SUBSTRING(HZ.T_ASPQH,1,4) + '-' + SUBSTRING(HZ.T_ASPQH,5,2) + '-' + SUBSTRING(HZ.T_ASPQH,7,2)
         AS DATE)                                                       AS [Value Date],
    CAST(CONVERT(INT, CONVERT(VARCHAR,HZ.MOTSR_MOZMN)) AS VARCHAR) + '-' +
    CAST(CONVERT(INT, CONVERT(VARCHAR,HZ.MOTSR_MOZMN)) AS VARCHAR)      AS ItemKey,
    t.UnitNetPriceUSD                                                   AS UnitNetPriceUSD,
    HZ.CMOT_MOZMNT                                                      AS Quantity,
    t.OrderQuantity                                                     AS OrderQuantity,
    999                                                                 AS PNLKey,
	1010  as [PNL Code],
    t.LineTotalNetUSD                                                  AS LineTotalNetUSD,
    CONVERT(INT, CONVERT(VARCHAR, SUBSTRING(HZ.T_ASPQH,1,4) + SUBSTRING(HZ.T_ASPQH,5,2))) AS YearMonth,
    t.ShipID                                                            AS ShipID,  -- ship from the related purchase order
    'Order'                                                             AS DocType,
    SM.NEW_SHER,
    t.Purchase                                                          AS MatchedImportPO
FROM HZMNOT HZ
LEFT JOIN CurrencyConvertion SM
    ON SM.TARIKH = HZ.T_HZMNH
LEFT JOIN exchange_priced t
    ON t.Exchange_order = HZ.MSPR_HZMNH
   AND t.ItemKey =
        CAST(CONVERT(INT, CONVERT(VARCHAR,HZ.MOTSR_MOZMN)) AS VARCHAR) + '-' +
        CAST(CONVERT(INT, CONVERT(VARCHAR,HZ.MOTSR_MOZMN)) AS VARCHAR)
   AND t.rn = 1
LEFT JOIN Swap_RootSupplier rs
    ON rs.OrderID = HZ.MSPR_HZMNH
WHERE CAST(SUBSTRING(HZ.T_HZMNH,1,4) AS INT) BETWEEN 2018 AND YEAR(GETDATE())
  AND HZ.OrderStatus <> 3
  AND HZ.ActionType IN (6,7)
  AND CAST(SUBSTRING(HZ.T_ASPQH,1,4) + '-' + SUBSTRING(HZ.T_ASPQH,5,2) + '-' + SUBSTRING(HZ.T_ASPQH,7,2) AS DATE) >= @CutoffDate
  )
SELECT * INTO #purchase_orders FROM purchase_orders;

-- ======================================================================
-- Step: materialize P_costs
;WITH po_doctype AS (
    SELECT DISTINCT
        PurchaseOrderID,
        CASE
            WHEN EXISTS (
                SELECT 1 FROM #purchase_orders pe2
                WHERE pe2.PurchaseOrderID = pe.PurchaseOrderID
                  AND pe2.DocName = 'Import'
            ) THEN 'Import'
            WHEN EXISTS (
                SELECT 1 FROM #purchase_orders pe2
                WHERE pe2.PurchaseOrderID = pe.PurchaseOrderID
                  AND pe2.DocName = 'Swap'
            ) THEN 'Swap'
            ELSE 'Invoice'
        END AS DocName
    FROM #purchase_orders pe
)

-- A swap PO can match against more than one candidate import (exchange_priced ranks a match
-- independently per DeliveredFrom/ItemKey/Date partition), giving purchase_orders several rows
-- with different MatchedImportPO/ShipID pairs for the same swap PurchaseOrderID. P_costs used to
-- pick 'boat' via its own independent MAX(ShipID) and MatchedImportPO via MAX(pe.MatchedImportPO)
-- — two unrelated tie-breaks that can (and did) land on different imports, showing one ship's
-- name next to another ship's CIF price. This CTE picks ONE winning row per swap PO (same
-- MAX(MatchedImportPO) tie-break as before) and carries THAT row's own ShipID forward, so boat
-- always names the same import MatchedImportPO/Cif_price actually come from.
,
Swap_WinningMatch AS (
    SELECT PurchaseOrderID, MatchedImportPO, ShipID
    FROM (
        SELECT
            pe.PurchaseOrderID,
            pe.MatchedImportPO,
            pe.ShipID,
            ROW_NUMBER() OVER (
                PARTITION BY pe.PurchaseOrderID
                ORDER BY pe.MatchedImportPO DESC
            ) AS rn
        FROM #purchase_orders pe
        WHERE pe.MatchedImportPO IS NOT NULL
    ) x
    WHERE rn = 1
)
,
P_costs AS (
    select
	pe.PurchaseOrderID,
	dt.DocName,
	min([Value Date]) as ValueDate,
	max(case when [PNLKey] = 999 then SupplierKey else null end) as SupplierKey,
	CASE WHEN dt.DocName = 'Swap' THEN MAX(sw.ShipID) ELSE MAX(pe.ShipID) END as boat,
	SUM(CASE WHEN [PNL Code] = 2270 THEN LineTotalNetUSD ELSE 0 END) as DischargeCosts,
	SUM(CASE WHEN [PNL Code] = 1201 THEN LineTotalNetUSD ELSE 0 END) as DemurrageCosts,
	CAST(ROUND(SUM(CASE WHEN [PNL Code] = 1111 THEN LineTotalNetUSD ELSE 0 END) / NULLIF(SUM(orderquantity), 0), 2) AS FLOAT) as [Shortage],
	CAST(ROUND(SUM(CASE WHEN [PNL Code] not in (1010,2270,1201,1111) THEN LineTotalNetUSD ELSE 0 END) / NULLIF(SUM(orderquantity), 0), 2) AS FLOAT) as [Other_Expenses],
	-- Swap rows repeat the same t.OrderQuantity on every row, so SUM would multiply it by the
	-- row count; Invoice/Import zero out non-header rows, so SUM is correct there.
	CASE WHEN dt.DocName = 'Swap' THEN MAX(orderquantity) ELSE SUM(orderquantity) END as orderquantity,
	sum(LineTotalNetUSD) as LineTotalNetUSD,
	CAST(ROUND(
		SUM(CASE WHEN PNLKey = 999 THEN LineTotalNetUSD ELSE 0 END)
		/ NULLIF(SUM(CASE WHEN PNLKey = 999 THEN OrderQuantity ELSE 0 END), 0)
	, 2) AS FLOAT) AS Cif_price,
	MAX(pe.NEW_SHER) AS NEW_SHER,
	MAX(pe.MatchedImportPO) AS MatchedImportPO
  from #purchase_orders pe
  LEFT JOIN po_doctype dt ON dt.PurchaseOrderID = pe.PurchaseOrderID
  LEFT JOIN Swap_WinningMatch sw ON sw.PurchaseOrderID = pe.PurchaseOrderID
  group by pe.PurchaseOrderID, dt.DocName
  )
SELECT * INTO #P_costs FROM P_costs;

-- ======================================================================
-- Step: final result
;WITH CurrencyConvertion AS (
SELECT *, 
         CASE
         	WHEN sher = 0
         	THEN FIRST_VALUE(sher) OVER (PARTITION BY value_partition ORDER BY Tarikh) 
         	ELSE sher
         END AS new_sher
         ,CASE
         	WHEN SHER_EURO = 0
         	THEN FIRST_VALUE(SHER_EURO) OVER (PARTITION BY value_partitionEuro ORDER BY Tarikh) 
         	ELSE  SHER_EURO
         END AS new_sherEuro
 FROM (
          SELECT *
 ,SUM(CASE WHEN sher=0 THEN 0 ELSE 1 END) OVER (ORDER BY tarikh ) AS value_partition
 ,SUM(CASE WHEN SHER_EURO=0 THEN 0 ELSE 1 END) OVER (ORDER BY tarikh ) AS value_partitionEuro
          FROM SHERI_MTBE
 ) m
)

--------------------------------------------------------------- the below part should be a view is the database ----------------------------------------------------
,
inv AS (
    -- One row per (ItemKey, calendar-month): last day's price in that month.
    -- Price is set by item+date, not by warehouse — any warehouse shares the same item price.
    SELECT ItemKey, [Date], WH_Price
    FROM (
        SELECT
            CONVERT(VARCHAR, src.ItemKey) + '-' + CONVERT(VARCHAR, src.ItemKey) AS ItemKey,
            src.[Date],
            CAST(ROUND(src.LastFOTPrice,     2) AS FLOAT) AS LastFOTPrice,
            CAST(ROUND(src.WeightedExpenses, 2) AS FLOAT) AS WeightedExpenses,
            CAST(ROUND(COALESCE(NULLIF(src.WeightedExpenses, 0), src.LastFOTPrice), 2) AS FLOAT) AS WH_Price,
            ROW_NUMBER() OVER (
                PARTITION BY src.ItemKey, YEAR(src.[Date]), MONTH(src.[Date])
                ORDER BY src.[Date] DESC
            ) AS month_rn
        FROM (
            -- Regular warehouses
            SELECT
                inv.ProductID      AS ItemKey,
                inv.DueDate        AS [Date],
                pcost.FotFlat      AS LastFOTPrice,
                pcost.WeightedExpenses,
                inv.Version,
                ROW_NUMBER() OVER (PARTITION BY inv.DueDate, inv.SupplierID, inv.ProductID
                                   ORDER BY inv.Version DESC) AS MaxVersion
            FROM tblInventory inv
            LEFT JOIN tblProductsCost pcost
                ON  inv.DueDate   = pcost.DueDate
                AND inv.ProductID = pcost.ProductCode
                AND inv.Version   = pcost.Version
            WHERE inv.SupplierID IN (1411, 1367, 1366, 1289, 1101, 943)
              AND inv.DueDate >= @CutoffDate

            UNION ALL

            -- Warehouse 1144: items from BT movements, prices from tblProductsCost
            SELECT
                tm.ItemKey,
                pc.DueDate         AS [Date],
                pc.FotFlat         AS LastFOTPrice,
                pc.WeightedExpenses,
                mv.MAXVERSION      AS Version,
                ROW_NUMBER() OVER (PARTITION BY pc.DueDate, tm.ItemKey
                                   ORDER BY mv.MAXVERSION DESC) AS MaxVersion
            FROM (
                SELECT DISTINCT QOD_PRIT AS ItemKey,
                       CAST(SUBSTRING(T_TNOEH,1,4)+'-'+SUBSTRING(T_TNOEH,5,2)+'-'+SUBSTRING(T_TNOEH,7,2) AS DATE) AS [Date]
                FROM BT.dbo.TNOEOT_MLAI_CLLI
                WHERE QOD_GORM <> 1
                  AND CAST(SUBSTRING(T_TNOEH,1,4)+'-'+SUBSTRING(T_TNOEH,5,2)+'-'+SUBSTRING(T_TNOEH,7,2) AS DATE) >= @CutoffDate
                  AND (SOG_TNOEH_CN_ITS_SP_HE LIKE N'%כ%' OR SOG_TNOEH_CN_ITS_SP_HE LIKE N'%י%')
            ) tm
            LEFT JOIN (SELECT DueDate, ProductCode, MAX(Version) AS MAXVERSION
                       FROM tblProductsCost
                       GROUP BY DueDate, ProductCode) mv
                ON  mv.DueDate     = tm.[Date]
                AND mv.ProductCode = tm.ItemKey
            LEFT JOIN tblProductsCost pc
                ON  pc.Version     = mv.MAXVERSION
                AND pc.DueDate     = mv.DueDate
                AND pc.ProductCode = mv.ProductCode
            GROUP BY tm.ItemKey, pc.DueDate, pc.FotFlat, pc.WeightedExpenses, mv.MAXVERSION
        ) src
        WHERE src.MaxVersion = 1
    ) daily
    WHERE daily.month_rn = 1
)

-- Resolves the primary DocName per PurchaseOrderID before aggregation.
-- A PO can have rows of multiple types (e.g. Import + Invoice).
-- Priority: Import > Exchange > Invoice.
,
sales AS (
  SELECT 
	'Invoice' AS 'DocName'
		,Case
			WHEN CS.QOD_MOTSR = TM.QOD_MOTSR
				THEN 'Item'
			ELSE 'Additional Expense'
		END AS 'LineType'
		,CONVERT(VARCHAR,CS.QOD_LQOCH) 'AccountKey' -- customer from invoices in case you need just invoices 
		,SUBSTRING(CS.T_CHSHBONIT,1,4) + '-' + SUBSTRING(CS.T_CHSHBONIT,5,2) + '-' + SUBSTRING(CS.T_CHSHBONIT,7,2) AS 'Date' -- Invoice date
		,CAST( CONVERT(VARCHAR,CS.QOD_MOTSR) as varchar) +'-' + CAST( CONVERT(VARCHAR,CS.QOD_MOTSR) as varchar) AS 'ItemKey'
		,CAST(CONVERT(VARCHAR,M.MasterProductInPurchase) as varchar) +'-' + CAST(CONVERT(VARCHAR,M.MasterProductInPurchase) as varchar) AS [מוצר על]
		,CAST(ROUND(CS.MCHIR_ICH_LLA_ME_M / NULLIF(CASE WHEN SHER_LCHISHOB <> 0 THEN SHER_LCHISHOB ELSE 1 END, 0), 2) AS FLOAT) AS 'UnitNetPriceUSD'
		,cast(ROUND(CS.MSHQL_NTO,2)AS FLOAT)  AS 'Quantity'
		,case
		when TM.ActionType = 11 and CS.QOD_MOTSR = TM.QOD_MOTSR then TM.MSHQL_NTO
		else 0 end
	as qty_cif
	,case
		when TM.ActionType = 1 and CS.QOD_MOTSR = TM.QOD_MOTSR then TM.MSHQL_NTO
		else 0 end
	as qty_fot
	,case
		when TM.ActionType = 1 then 'FOT'
		WHEN TM.ActionType = 11 then 'CIF'
		WHEN TM.ActionType = 12 then 'FOT Premium'
	else null 
	end as SalesType
		,CASE
			WHEN CS.QOD_MOTSR=TM.QOD_MOTSR
				THEN 0
			ELSE Cs.CMOT
		END as AdditionalQuantity
		,CAST(ROUND(
			CASE
				WHEN CS.QOD_MOTSR <> 0
					THEN (CS.MCHIR_ICH_LLA_ME_M * CS.MSHQL_NTO) / NULLIF(CASE WHEN SHER_LCHISHOB <> 0 THEN SHER_LCHISHOB ELSE CC.new_sher END, 0)
				ELSE CS.MCHIR_ICH_LLA_ME_M / NULLIF(CASE WHEN SHER_LCHISHOB <> 0 THEN SHER_LCHISHOB ELSE CC.new_sher END, 0)
			END
			+
			CASE
				WHEN CS.QOD_MOTSR = TM.QOD_MOTSR THEN 0
				WHEN TM.QOD_MOTSR IS NULL         THEN 0
				ELSE Cs.CMOT * (CS.MCHIR_ICH_LLA_ME_M / NULLIF(CASE WHEN SHER_LCHISHOB <> 0 THEN SHER_LCHISHOB ELSE CC.new_sher END, 0))
			END
		, 2) AS FLOAT) AS 'LineTotalNet_USD' --Invoices are always in NIS
		,CONVERT(INT, CONVERT(VARCHAR,SUBSTRING(CS.T_CHSHBONIT,1,4) + SUBSTRING(CS.T_CHSHBONIT,5,2))) AS YearMonth
		, TM.MS_TEODH as 'DeliveryNote'
		,CASE
			WHEN SUBSTRING(TM.TARIKH_MSHLOCH,1,4) = '0000'
				THEN CAST(SUBSTRING(CS.T_CHSHBONIT,1,4) + '-' + SUBSTRING(CS.T_CHSHBONIT,5,2) + '-' + SUBSTRING(CS.T_CHSHBONIT,7,2) as date)
			ELSE CAST(ISNULL(SUBSTRING(TM.TARIKH_MSHLOCH,1,4) + '-' + SUBSTRING(TM.TARIKH_MSHLOCH,5,2) + '-' + SUBSTRING(TM.TARIKH_MSHLOCH,7,2),
		ISNULL(SUBSTRING(FTM.FirstDeliveryDateTM,1,4) + '-' + SUBSTRING(FTM.FirstDeliveryDateTM,5,2) + '-' + SUBSTRING(FTM.FirstDeliveryDateTM,7,2),
		SUBSTRING(CS.T_CHSHBONIT,1,4) + '-' + SUBSTRING(CS.T_CHSHBONIT,5,2) + '-' + SUBSTRING(CS.T_CHSHBONIT,7,2)))
		AS date) 
		END as 'DeliveryDate'
		,HZ.MSPR_HZMNH as 'OrderID'
		,TM.QOD_SHOLCH as 'SupplierWarehouse'
		,TM.ActionType							as 'ActionType'
		,CASE 
			WHEN TM.ActionType = 6 THEN G.AOPI_PEILOT
			ELSE act.ActionType
		END										as 'ActionTypeDesc'										
		,'0'									as 'AdjustmentFlag'
		,'Sales'								as  'QuantityCategory'
FROM CHSHBONIOT_COTROT CH
Left Join GORMIM G
	on CH.QOD_LQOCH = G.QOD_GORM
Left Join TBLT_ANSHI_MCIROT AM 
	on AM.SHM_AISH_MCIROT = G.AISH_MCIROT_MTPL
LEFT JOIN CHSHBONIOT_SHOROT CS 
    ON CH.MS_CHSHBONIT = CS.MS_CHSHBONIT
--New line to add product family
LEFT JOIN MOTSRIM M
	ON CS.QOD_MOTSR = M.QOD_MOTSR
	--end here
LEFT JOIN TEODOT_MSHLOCH TM 
	ON CS.MS_T_MSHLOCH = TM.MS_TEODH
LEFT JOIN (SELECT MS_CHSHBONIT , Min (TM.TARIKH_MSHLOCH) as 'FirstDeliveryDateTM',Min (CHS.TARIKH_MSHLOCH) as 'FirstDeliveryDateCHS'
			FROM CHSHBONIOT_SHOROT CHS
			Left Join TEODOT_MSHLOCH TM
				ON TM.MS_TEODH = CHS.MS_T_MSHLOCH
			Where 1=1
			AND TM.TARIKH_MSHLOCH <>00000000
			AND CHS.TARIKH_MSHLOCH <>00000000
			Group By CHS.MS_CHSHBONIT) FTM
	ON FTM.MS_CHSHBONIT = CH.MS_CHSHBONIT
Left Join (SELECT MS_HZMNH,MS_T_MSHLOCH
			FROM QISHOR_T_MSHLOCH_HZMNOT
			) HZT
	on TM.MS_TEODH = HZT.MS_T_MSHLOCH
Left Join HZMNOT HZ
	on HZ.MSPR_HZMNH = HZT.MS_HZMNH
left join TBLT_PEOLOT_HZMNH_T_MSHLOCH act
	on TM.ActionType = act.MS_AOPTSIH
left join CurrencyConvertion CC 
	ON cs.[TARIKH_MSHLOCH] = cc.Tarikh
WHERE 1=1
AND CAST(SUBSTRING(cs.T_CHSHBONIT,1,4) + '-' + SUBSTRING(cs.T_CHSHBONIT,5,2) + '-' + SUBSTRING(cs.T_CHSHBONIT,7,2) AS DATE) >= @CutoffDate
AND TM.QOD_SHOLCH <> TM.QOD_MQBL
AND CS.QOD_MOTSR <> 96

-------OPEN Orders----------------------------------------------------------------------------------
UNION ALL

 SELECT 
	'Delivery Note' as  'DocName'
	,'Item' AS 'LineType'
	,CONVERT(INT, CONVERT(VARCHAR, TM.QOD_MQBL)) AS 'AccountKey'
	,SUBSTRING(TARIKH_MSHLOCH,1,4) + '-' + SUBSTRING(TARIKH_MSHLOCH,5,2) + '-' + SUBSTRING(TARIKH_MSHLOCH,7,2) as 'Date'
	,CONVERT(VARCHAR, TM.QOD_MOTSR)+'-'+CONVERT(VARCHAR, TM.QOD_MOTSR) AS 'ItemKey'
	,CAST(CONVERT(VARCHAR,M.MasterProductInPurchase) as varchar) +'-' + CAST(CONVERT(VARCHAR,M.MasterProductInPurchase) as varchar) AS [מוצר על]
	,CAST(ROUND(CASE
	         WHEN TM.MTBE_SH = '$' THEN TM.MCHIR_ICH
	         ELSE TM.MCHIR_ICH * (1 / NULLIF(SM.NEW_SHER, 0))
         END, 2) AS FLOAT) AS 'UnitNetPriceUSD'
	,cast(ROUND(TM.MSHQL_NTO,2)AS FLOAT) as 'Quantity'
	,case
		when TM.ActionType = 11 then TM.MSHQL_NTO
		else 0 end
	as qty_cif
	,case
		when TM.ActionType = 1 then TM.MSHQL_NTO
		else 0 end
	as qty_fot
	,case
		when TM.ActionType = 1 then 'FOT'
		WHEN TM.ActionType = 11 then 'CIF'
		WHEN TM.ActionType = 12 then 'FOT Premium'
	else null 
	end as SalesType
	,0 AS 'AdditionalQuantity'
	,CAST(ROUND(CASE
	         WHEN TM.MTBE_SH = '$'
		     THEN TM.MCHIR_ICH * TM.MSHQL_NTO /*TM.CMOT_SHSOPQH*/
	         ELSE TM.MCHIR_ICH * TM.MSHQL_NTO /*TM.CMOT_SHSOPQH*/ * (1 / NULLIF(SM.NEW_SHER, 0))
         END, 2) AS FLOAT) AS 'LineTotalNet_USD'
	,CONVERT(INT, CONVERT(VARCHAR,SUBSTRING(T_ASPQH,1,4) + SUBSTRING(T_ASPQH,5,2))) AS YearMonth
	,TM.MS_TEODH as 'DeliveryNote'
	,CAST(SUBSTRING(TARIKH_MSHLOCH,1,4) + '-' + SUBSTRING(TARIKH_MSHLOCH,5,2) + '-' + SUBSTRING(TARIKH_MSHLOCH,7,2) as date) as 'DeliveryDate'
	,HZ.MSPR_HZMNH as 'OrderID'
	,TM.QOD_SHOLCH as 'SupplierWarehouse'
	,TM.ActionType							as 'ActionType'
	,CASE 
		WHEN TM.ActionType = 6 THEN G.AOPI_PEILOT
		ELSE act.ActionType
	END as 'ActionTypeDesc'
	,CASE
	WHEN TM.MCHIR_ICH = 0
		THEN '1'
	ELSE '0'
	END AS 'AdjustmentFlag'
	,CASE
		WHEN TM.MCHIR_ICH <> 0 THEN 'Sales'
		WHEN TM.MCHIR_ICH = 0 and G.AOPI_PEILOT = 'פחת' THEN 'Shortage'
		WHEN TM.MCHIR_ICH = 0 and G.AOPI_PEILOT = 'אחסון' THEN 'Storage'
		WHEN TM.MCHIR_ICH = 0 and G.AOPI_PEILOT NOT IN ('פחת','אחסון') then 'Swap'
	END AS 'QuantityCategory'
FROM TEODOT_MSHLOCH TM
Left Join (SELECT distinct MS_T_MSHLOCH
			FROM CHSHBONIOT_SHOROT
		) CH
	on TM.MS_TEODH = CH.MS_T_MSHLOCH
LEFT JOIN MOTSRIM M
	ON TM.QOD_MOTSR = M.QOD_MOTSR
Left Join (SELECT MS_HZMNH,MS_T_MSHLOCH
			FROM QISHOR_T_MSHLOCH_HZMNOT
		) HZT
	on TM.MS_TEODH = HZT.MS_T_MSHLOCH
Left Join HZMNOT HZ
	on HZ.MSPR_HZMNH = HZT.MS_HZMNH
LEFT JOIN CurrencyConvertion SM  -- reuse top-level CTE instead of repeating SHERI_MTBE inline
	ON SM.TARIKH = HZ.T_HZMNH
Left Join GORMIM G
	on TM.QOD_MQBL = G.QOD_GORM
Left Join (
			Select *
			From GORMIM
			Where EntityType Like N'%מקום אספקה%') W
	On W.QOD_GORM = TM.QOD_SHOLCH
left join TBLT_PEOLOT_HZMNH_T_MSHLOCH act
	on TM.ActionType = act.MS_AOPTSIH
WHERE
CH.MS_T_MSHLOCH is null
AND CAST(SUBSTRING(TARIKH_MSHLOCH,1,4) + '-' + SUBSTRING(TARIKH_MSHLOCH,5,2) + '-' + SUBSTRING(TARIKH_MSHLOCH,7,2) AS DATE) >= @CutoffDate
AND STTOS in (0,1)
AND TM.PurchaseOrderType = 0
AND TM.QOD_MOTSR <> 96 
AND TM.QOD_SHOLCH <> TM.QOD_MQBL   -- exclude internal docs (same source and destination)
  )
,
base_link AS (
  SELECT distinct
        a.MS_TEODT_MCIRH AS DeliveryNote,
        b.MS_HZMNH AS PurchaseOrderID
    FROM QISHOR_RCSH_LMCIRH a
    LEFT JOIN QISHOR_T_MSHLOCH_HZMNOT b
        ON a.MS_TEODT_RCSH = b.MS_T_MSHLOCH

		)
,
CIF_Qty AS (
    SELECT
        bl.PurchaseOrderID,
        SUM(s.qty_cif) AS CIF_Qty
    FROM sales s
    INNER JOIN base_link bl
        ON bl.DeliveryNote = s.DeliveryNote
    GROUP BY bl.PurchaseOrderID
)

-- Warehouse sales: delivery notes that have no entry in base_link are not linked to any
-- purchase order, meaning they originate from a warehouse (not import or exchange).
,
WH_sales AS (
    SELECT
        s.DeliveryNote,
        s.DeliveryDate,
        FORMAT(s.DeliveryDate, 'yyyy-MM')                                           AS [Year-Month],
        s.AccountKey,
        s.ActionType,
        s.ActionTypeDesc,
        s.SupplierWarehouse,
        s.AdjustmentFlag,
        s.QuantityCategory,
        -- ItemKey, sale price, and SalesType come from the 'Item' line only
        MAX(CASE WHEN s.LineType = 'Item' THEN s.ItemKey        ELSE NULL END)      AS ItemKey,
		MAX(CASE WHEN s.LineType = 'Item' THEN s.[מוצר על]        ELSE NULL END)   AS [מוצר על],
        MAX(CASE WHEN s.LineType = 'Item' THEN s.SalesType      ELSE NULL END)      AS SalesType,
        MAX(CASE WHEN s.LineType = 'Item' THEN s.UnitNetPriceUSD ELSE NULL END)     AS UnitNetPriceUSD,
        -- Quantity = item qty only (excludes storage/additional-expense qty)
        SUM(CASE WHEN s.LineType = 'Item' THEN s.Quantity       ELSE 0   END)       AS Quantity,
        -- Total revenue = all lines combined (item + storage fee)
        SUM(s.LineTotalNet_USD)                                                     AS LineTotalNet_USD,
        -- Additional-line cost: the value of non-item lines (e.g. warehouse storage fee).
        -- Non-zero only when MultiLineFlag = 1; use this to compare WH additional costs vs other order types.
        SUM(CASE WHEN s.LineType <> 'Item' THEN s.LineTotalNet_USD ELSE 0 END)      AS AdditionalLineCost,
        SUM(s.AdditionalQuantity)                                                   AS AdditionalQuantity,
        -- 1 = delivery note had multiple lines (e.g. item + warehouse storage fee), 0 = single line
		CASE 
			WHEN COUNT(*) > 1 or MAX(CASE WHEN s.LineType = 'Item' THEN s.ItemKey ELSE NULL END) = '42-42' THEN '1' 	
			ELSE '0' 
		END																			 AS MultiLineFlag
    FROM sales s
    LEFT OUTER JOIN base_link bl ON bl.DeliveryNote = s.DeliveryNote
	WHERE s.SupplierWarehouse in (1144,1411,1367,1366,1289,1101,943)
    GROUP BY
        s.DeliveryNote, s.DeliveryDate, --s.ItemKey,
        s.AccountKey,
        s.ActionType, s.ActionTypeDesc,
        s.SupplierWarehouse, 
        s.AdjustmentFlag, s.QuantityCategory
)
,
WH_prices AS (
    SELECT
        *,
        CASE
			WHEN ItemKey = '42-42' THEN CAST(ROUND((LineTotalNet_USD - AdditionalLineCost) / NULLIF(Quantity, 0), 2) AS FLOAT) - 12
			WHEN Quantity > 0 THEN CAST(ROUND((LineTotalNet_USD - AdditionalLineCost) / NULLIF(Quantity, 0), 2) AS FLOAT)
             ELSE NULL END                                                                       AS Item_Price,
        CASE 
			WHEN ItemKey = '42-42' THEN CAST(12 AS FLOAT)
			WHEN AdditionalQuantity > 0 THEN CAST(ROUND(AdditionalLineCost / NULLIF(AdditionalQuantity, 0), 2) AS FLOAT)
             ELSE NULL END                                                                       AS Storage_Price,
        CASE 
			WHEN AdjustmentFlag <> '1' THEN CAST(ROUND((LineTotalNet_USD - AdditionalLineCost) / NULLIF(Quantity, 0) +ISNULL(AdditionalLineCost / NULLIF(AdditionalQuantity, 0), 0),2) AS FLOAT)
             ELSE NULL END                                                                       AS Total_Price
    FROM WH_sales
)

-- ============================================================
-- Branch 1: Import / Exchange orders — cost from #P_costs
-- ============================================================
SELECT
	cast(s.DeliveryNote as varchar)																							AS DeliveryNote,
	s.LineType																												AS LineType,
	s.QuantityCategory																										AS QuantityCategory,
	s.ActionTypeDesc																										AS ActionTypeDesc,
	PC.DocName																												AS Purchase_DocName,
	s.AdjustmentFlag																										AS AdjustmentFlag,
	case when s.rn = 1
		 then '1' else '0' end																								AS Qty_flag,
	'0'																														AS MultiLineFlag,
	'0'																														AS wh_flag,
	cast(s.PurchaseOrderID as varchar)																						AS PurchaseOrderID,
	cast(PC.SupplierKey as varchar)																							AS SupplierKey,
	cast(s.AccountKey as varchar)																							AS AccountKey,
	cast(s.ItemKey as varchar)																								AS ItemKey,
	cast(PC.boat as varchar)																								AS ShipID,
	FORMAT(PC.ValueDate, 'yyyy-MM')																							AS [Year-Month],
	PC.ValueDate																											AS ValueDate,
	s.DeliveryDate																											AS DeliveryDate,
	case when s.SalesType is null then s.QuantityCategory
		 else s.SalesType end																								AS [Price Term],
	s.Quantity																												AS Quantity,
	case
		when s.rn = 1 and PC.DocName = 'Swap' then sum(s.Quantity) over (partition by s.PurchaseOrderID)
		when s.rn = 1 and PC.DocName = 'Import' then PC.orderquantity
	else 0 end																												AS PurchaseQuantity,
	s.LineTotalNet_USD																										AS LineTotalNet_USD,
	NULL																													AS Item_Price,
	NULL																													AS Storage_Price,
	CASE WHEN s.AdjustmentFlag <> 1
		 THEN CAST(ROUND(s.LineTotalNet_USD / NULLIF(s.Quantity, 0), 2) AS FLOAT)
		 ELSE NULL END																										AS Total_Price,
	s.UnitNetPriceUSD																										AS UnitNetPriceUSD,
	-- For Swap rows, pull the matched import's own already-computed CIF/demurrage/discharge
	-- straight from ImportPC (P_costs joined again, keyed on PC.MatchedImportPO) instead of
	-- PC (the swap PO's own P_costs row) — this is the exact, single-source-of-truth number
	-- P_costs reports for that import elsewhere in the model, not a recalculation.
	case when s.rn = 1
	then ISNULL(ImportPC.Cif_price, PC.Cif_price) else 0 end																AS CIF_Purchase,
	CASE
		WHEN s.rn = 1 THEN
		CAST(ROUND(ISNULL(
			ISNULL(ImportPC.DemurrageCosts, PC.DemurrageCosts)
			/ NULLIF(ISNULL(ImportPC.orderquantity, PC.orderquantity) - ISNULL(cq.CIF_Qty, 0), 0)
		, 0), 2) AS FLOAT)
		ELSE 0 END																											AS [demurrage / Despatch],
	CASE WHEN s.rn = 1 THEN PC.[Other_Expenses]     ELSE 0 END																AS [Other_Expenses],
	CASE WHEN s.rn = 1 THEN PC.Shortage            ELSE 0 END																AS Shortage,
	CASE
		WHEN s.rn = 1 THEN
		CAST(ROUND( ISNULL(
			ISNULL(ImportPC.DischargeCosts, PC.DischargeCosts)
			/ NULLIF(ISNULL(ImportPC.orderquantity, PC.orderquantity) - ISNULL(cq.CIF_Qty, 0), 0)
		, 0), 2) AS FLOAT) END 		AS DischargeCost_Base,
	CASE
		WHEN s.rn = 1 THEN
		CAST(ROUND(ISNULL(ImportPC.Cif_price, PC.Cif_price) +
		ISNULL(
			ISNULL(ImportPC.DemurrageCosts, PC.DemurrageCosts)
			/ NULLIF(ISNULL(ImportPC.orderquantity, PC.orderquantity) - ISNULL(cq.CIF_Qty, 0), 0)
		, 0) +
		ISNULL(
			ISNULL(ImportPC.DischargeCosts, PC.DischargeCosts)
			/ NULLIF(ISNULL(ImportPC.orderquantity, PC.orderquantity) - ISNULL(cq.CIF_Qty, 0), 0)
		, 0),2) AS FLOAT)
		ELSE 0 END																											AS FOT_Purchase,
	CAST(ROUND(CASE
		WHEN s.SalesType = 'CIF' AND s.LineType = 'Item'
		THEN ((s.LineTotalNet_USD / NULLIF(s.Quantity, 0)) - ISNULL(ImportPC.Cif_price, PC.Cif_price)) * s.Quantity
		WHEN s.SalesType IN ('FOT', 'FOT Premium') AND s.LineType = 'Item'
		THEN ((s.LineTotalNet_USD / NULLIF(s.Quantity, 0)) -
		(ISNULL(ImportPC.Cif_price, PC.Cif_price)
			+ ISNULL(ISNULL(ImportPC.DemurrageCosts, PC.DemurrageCosts) / NULLIF(ISNULL(ImportPC.orderquantity, PC.orderquantity) - ISNULL(cq.CIF_Qty, 0), 0), 0)
			+ (ISNULL(ImportPC.DischargeCosts, PC.DischargeCosts)/ NULLIF(ISNULL(ImportPC.orderquantity, PC.orderquantity) - ISNULL(cq.CIF_Qty, 0),0)))) * s.Quantity
		ELSE 0 END, 2) AS FLOAT)																							AS TotalGain,
		NULL																												AS AdditionalLineCost
FROM (
    SELECT s.*,
           bl.PurchaseOrderID,
           ROW_NUMBER() OVER (PARTITION BY bl.PurchaseOrderID ORDER BY s.DeliveryNote ASC) AS rn
    FROM sales s
    INNER JOIN base_link bl ON bl.DeliveryNote = s.DeliveryNote
	) s
	LEFT JOIN  #P_costs PC   ON PC.PurchaseOrderID = CAST(s.PurchaseOrderID AS VARCHAR(30))
	-- Second P_costs join: only matters for Swap rows (PC.MatchedImportPO is NULL for
	-- Invoice/Import), pulls the matched import's own CIF/demurrage/discharge directly.
	LEFT JOIN #P_costs ImportPC ON ImportPC.PurchaseOrderID = PC.MatchedImportPO
	LEFT JOIN CIF_Qty cq    ON cq.PurchaseOrderID = ISNULL(PC.MatchedImportPO, s.PurchaseOrderID)
	WHERE PC.ValueDate IS NOT NULL

UNION ALL

-- ============================================================
-- Branch 2: Warehouse orders — cost from inv (LastCFPrice)
-- ============================================================
SELECT
    CAST(s.DeliveryNote AS VARCHAR)																							AS DeliveryNote,
	'Item'																													AS LineType,
	s.QuantityCategory																										AS [QuantityCategory],
    s.ActionTypeDesc																										AS [ActionTypeDesc],
    'Warehouse'																												AS Purchase_DocName,
	s.AdjustmentFlag																										AS [AdjustmentFlag],
	'0'																														AS Qty_flag,
	case 
		when s.Storage_Price is null then '0' --to ignore the discount
		else s.MultiLineFlag		end																						AS [MultiLineFlag],
	case when row_number() over
	(partition by s.SupplierWarehouse, FORMAT(s.DeliveryDate, 'yyyy-MM'), s.ItemKey
	order by s.DeliveryNote asc) = 1
         then '1' else '0' end																								AS wh_flag,
    CAST(s.SupplierWarehouse AS VARCHAR(10)) + '_' +
	FORMAT(s.DeliveryDate, 'yyyyMM') + '_' + CAST(s.ItemKey AS VARCHAR)														AS PurchaseOrderID,
    CAST(s.SupplierWarehouse AS VARCHAR)																					AS SupplierKey,
	CAST(s.AccountKey AS VARCHAR)																							AS AccountKey,
    CAST(s.ItemKey AS VARCHAR)																								AS ItemKey,
    NULL																													AS ShipID,
	FORMAT(s.DeliveryDate, 'yyyy-MM')																						AS [Year-Month],
    CAST(FORMAT(s.DeliveryDate, 'yyyy-MM') + '-01' AS DATE)																	AS ValueDate,
    s.DeliveryDate																											AS [DeliveryDate],			
    CASE WHEN s.SalesType IS NULL THEN s.QuantityCategory
         ELSE s.SalesType END																								AS [Price Term],
	s.Quantity																												AS [Quantity],
	s.Quantity																												AS PurchaseQuantity,
    s.LineTotalNet_USD																										AS [LineTotalNet_USD],
    s.Item_Price                                                                                                            AS Item_Price,
    s.Storage_Price                                                                                                         AS Storage_Price,
    s.Total_Price                                                                                                           AS Total_Price,
    s.UnitNetPriceUSD																										AS [UnitNetPriceUSD],
    NULL																													AS CIF_Purchase,  -- no CIF concept for warehouse
    NULL																													AS [demurrage / Despatch],
    NULL																													AS [Other_Expenses],
    NULL																													AS Shortage,
    NULL																													AS DischargeCost_Base,
    inv.WH_Price																											AS FOT_Purchase,
    CASE WHEN s.AdjustmentFlag <> 1
         THEN CAST(ROUND((s.LineTotalNet_USD / NULLIF(s.Quantity, 0)) - (16 + inv.WH_Price), 2) AS FLOAT) * s.Quantity
         ELSE 0 END																											AS TotalGain,
    s.AdditionalLineCost																									AS [AdditionalLineCost] --wh charge cost
FROM WH_prices s
LEFT JOIN inv
    ON  inv.ItemKey = 
	(CASE
           WHEN s.[מוצר על] <> '0-0' THEN s.[מוצר על]
           ELSE s.ItemKey
       END)
    AND FORMAT(inv.[Date], 'yyyyMM') = FORMAT(s.DeliveryDate, 'yyyyMM')
GO
SET STATISTICS IO, TIME OFF;
GO
-- dimPurchaseOrderNumber (before) - extracted from TMDL by extract_queries.py
-- Run on STG only. Before running: Query > Query Options > Results > Grid >
-- tick 'Discard results after execution', so SSMS does not render the rows.
PRINT '===== dimPurchaseOrderNumber | before =====';
SET STATISTICS IO, TIME ON;
GO

WITH
-- =========================
-- 1) Exchange Orders (parse dates once)
-- =========================
ExchangeOrders AS (
    SELECT
        HZ.MSPR_HZMNH AS OrderID,
        TRY_CONVERT(date, HZ.T_ASPQH, 112) AS [Value Date],
        CONVERT(char(6), TRY_CONVERT(date, HZ.T_ASPQH, 112), 112) AS [Year Month]
    FROM HZMNOT HZ
),
ExchangeOrdersOnly AS (
    SELECT
        HZ.MSPR_HZMNH,
        TRY_CONVERT(int, LEFT(HZ.T_HZMNH, 4)) AS OrderYear,
		'Exchange' as ExpenseSource
    FROM HZMNOT HZ
    WHERE
        TRY_CONVERT(int, LEFT(HZ.T_HZMNH, 4)) >= 2024
        AND TRY_CONVERT(int, LEFT(HZ.T_HZMNH, 4)) BETWEEN 2018 AND YEAR(GETDATE())
        AND HZ.OrderStatus <> 3
        AND HZ.ActionType IN (6, 7)
),

-- =========================
-- 2) Purchase Order value date/yearmonth (avoid DISTINCT + repeated logic)
-- =========================
PO_Base AS (
    SELECT
        HS.MS_MSMKH_QSHOR,
        -- Calculate the grouping key once
        CASE
            WHEN HS.MS_MSMKH_QSHOR = 0 THEN HZ.MSPR_HZMNH
            ELSE HS.MS_MSMKH_QSHOR
        END AS OrderKey,
        HS.QOD_SHROT,
        TRY_CONVERT(date, HC.T_ERKH, 112) AS DocDate
    FROM HOTSAOT_COTROT HC
    LEFT JOIN HOTSAOT_SHOROT HS
        ON HC.NOMRTOR = HS.NOMRTOR
    LEFT JOIN PurchaseOrderLines POL
        ON CONCAT(
            CAST(CONVERT(bigint, POL.POL_OrderID) AS varchar(20)),
            CAST(POL.POL_LineID AS varchar(10))
        ) = CAST(HS.MS_MSMKH_QSHOR AS varchar(30))
    LEFT JOIN HZMNOT HZ
        ON HS.MS_MSMKH_QSHOR = HZ.MSPR_HZMNH
)
,
Purchase_order AS (
    SELECT
        MS_MSMKH_QSHOR,
        -- Keep original behavior:
        -- If MS_MSMKH_QSHOR=0 take that row's DocDate, else take MIN DocDate where QOD_SHROT=0 per OrderKey.
        CASE
            WHEN MS_MSMKH_QSHOR = 0 THEN MAX(DocDate)
            ELSE MIN(CASE WHEN QOD_SHROT = 0 THEN DocDate END)
        END AS [Value Date],
        CASE
            WHEN MS_MSMKH_QSHOR = 0 THEN CONVERT(char(6), MAX(DocDate), 112)
            ELSE CONVERT(char(6), MIN(CASE WHEN QOD_SHROT = 0 THEN DocDate END), 112)
        END AS [Year Month]
    FROM PO_Base
    GROUP BY
        MS_MSMKH_QSHOR,
        OrderKey
),


-- =========================
-- 3) Shared enrichment for both Purchase + Exchange
-- =========================
BaseLink AS (
    SELECT
        a.MS_TEODT_MCIRH AS DeliveryNote,
        a.MS_TEODT_RCSH,
        b.MS_HZMNH AS PurchaseOrderID,
        ISNULL(sl.ShipDesc, '-') AS ShipDesc,
		CASE
			WHEN POL.POL_OrderID IS NULL THEN 'Other'
			ELSE 'Import'
			END											as ExpenseSource
    FROM QISHOR_RCSH_LMCIRH a
    LEFT JOIN QISHOR_T_MSHLOCH_HZMNOT b
        ON a.MS_TEODT_RCSH = b.MS_T_MSHLOCH
    LEFT JOIN PurchaseOrderLines POL
        ON b.MS_HZMNH = POL.POL_SQL_POID
    LEFT JOIN ShipsArrivals sa
        ON POL.POL_ShipArrivalID = sa.SA_ID
    LEFT JOIN ShipList sl
        ON sa.SA_ShipID = sl.ShipID	
)

-- =========================
-- 4) Purchase / Exchange (keep INNER JOIN filters)
-- =========================
,Purchase AS (
    SELECT
        bl.DeliveryNote,
        bl.MS_TEODT_RCSH,
        CAST(bl.PurchaseOrderID AS VARCHAR) as PurchaseOrderID,
        bl.ShipDesc,
		bl.ExpenseSource
    FROM BaseLink bl
    INNER JOIN PurchaseOrderLines polFilter
        ON bl.PurchaseOrderID = polFilter.POL_SQL_POID
    LEFT JOIN Purchase_order p
        ON bl.PurchaseOrderID = p.MS_MSMKH_QSHOR
    LEFT JOIN ExchangeOrders o
        ON bl.PurchaseOrderID = o.OrderID
),
Order_First_Date as (
select distinct
HZ.MSPR_HZMNH as 'Order',
min(SUBSTRING(TM.TARIKH_MSHLOCH,1,4) + '-' + SUBSTRING(TM.TARIKH_MSHLOCH,5,2) + '-' + SUBSTRING(TM.TARIKH_MSHLOCH,7,2)) over (partition by HZ.MSPR_HZMNH)
 AS 'FirstSalesDate'  
FROM CHSHBONIOT_SHOROT CS 
LEFT JOIN TEODOT_MSHLOCH TM ON CS.MS_T_MSHLOCH = TM.MS_TEODH
Left Join (SELECT MS_HZMNH,MS_T_MSHLOCH
			FROM QISHOR_T_MSHLOCH_HZMNOT
			) HZT
	on TM.MS_TEODH = HZT.MS_T_MSHLOCH
Left Join HZMNOT HZ
	on HZ.MSPR_HZMNH = HZT.MS_HZMNH
LEFT JOIN HOTSAOT_SHOROT HS
	 ON HS.MS_MSMKH_QSHOR = HZ.MSPR_HZMNH
where TM.ActionType = 1 

union all
-------------------Purchase----------------------
SELECT distinct
	b.MS_HZMNH 'Order',
	min(SUBSTRING(TM.TARIKH_MSHLOCH,1,4) + '-' + SUBSTRING(TM.TARIKH_MSHLOCH,5,2) + '-' + SUBSTRING(TM.TARIKH_MSHLOCH,7,2)) over (partition by b.MS_HZMNH) AS 'FirstSalesDate'
FROM QISHOR_RCSH_LMCIRH a
LEFT JOIN QISHOR_T_MSHLOCH_HZMNOT b
    ON a.MS_TEODT_RCSH = b.MS_T_MSHLOCH
LEFT JOIN TEODOT_MSHLOCH TM
	ON TM.MS_TEODH = b.MS_T_MSHLOCH 
),
Exchange AS (
    SELECT
        bl.DeliveryNote,
        bl.MS_TEODT_RCSH,
        CAST(bl.PurchaseOrderID AS VARCHAR) as PurchaseOrderID,
        bl.ShipDesc,
		ex.ExpenseSource
    FROM BaseLink bl
    INNER JOIN ExchangeOrdersOnly ex
        ON ex.MSPR_HZMNH = bl.PurchaseOrderID
    LEFT JOIN Purchase_order p
        ON bl.PurchaseOrderID = p.MS_MSMKH_QSHOR
    LEFT JOIN ExchangeOrders o
        ON bl.PurchaseOrderID = o.OrderID
),
Final as (
SELECT * FROM Purchase
UNION ALL
SELECT * FROM Exchange)
, RankedDeliveryNote AS (
    SELECT
        DeliveryNote,
        PurchaseOrderID,
        ShipDesc,
		ExpenseSource,
        ROW_NUMBER() OVER (
            PARTITION BY DeliveryNote
            ORDER BY PurchaseOrderID DESC) AS rn
    FROM Final
)

SELECT distinct
    RDN.PurchaseOrderID,
    RDN.ShipDesc,
	OFD.FirstSalesDate as [Value Date],
    CONVERT(char(7),OFD.FirstSalesDate, 120) as ValueDateMonth,
	RDN.ExpenseSource,
    DENSE_RANK() OVER (
            ORDER BY  CONVERT(char(7),OFD.FirstSalesDate, 120) DESC
        ) AS Sort
FROM RankedDeliveryNote RDN
left join Order_First_Date OFD on RDN.PurchaseOrderID = OFD.[Order]
WHERE rn = 1
GO
